import React, { useEffect, useMemo, useState } from 'react';
import type { BankStatementImportCreatedVoucher } from '../../../../../services/kt/bankStatementImportModels';
import styles from '../StepClassifyImp/StepClassifyImp.module.css';
import confirmStyles from './StepConfirmImp.module.css';

type Props = {
  vouchers: BankStatementImportCreatedVoucher[];
  testIdPrefix: string;
  onOpenVoucher?: (v: BankStatementImportCreatedVoucher) => void;
};

function money(n: number): string {
  return (n ?? 0).toLocaleString('vi-VN');
}

type CompanyGroup = {
  companyCode: string;
  vouchers: BankStatementImportCreatedVoucher[];
  totalAmount: number;
};

/**
 * Success sau Confirm — group Đơn vị → CT (ngày · mã · ĐK · tiền)
 * expand chi tiết sao kê gốc + IMP id / mã tham chiếu đối soát.
 */
export const ConfirmSuccessVoucherPanel: React.FC<Props> = ({
  vouchers,
  testIdPrefix,
  onOpenVoucher,
}) => {
  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const [openCompanies, setOpenCompanies] = useState<Set<string>>(() => new Set());
  const [openVouchers, setOpenVouchers] = useState<Set<string>>(() => new Set());

  const companies = useMemo((): CompanyGroup[] => {
    const map = new Map<string, BankStatementImportCreatedVoucher[]>();
    for (const v of vouchers) {
      const key = (v.companyCode || '').trim() || '(chưa đơn vị)';
      const arr = map.get(key) ?? [];
      arr.push(v);
      map.set(key, arr);
    }
    return [...map.entries()]
      .map(([companyCode, list]) => ({
        companyCode,
        vouchers: [...list].sort((a, b) =>
          (a.voucherDate || '').localeCompare(b.voucherDate || '')
          || a.voucherCode.localeCompare(b.voucherCode)),
        totalAmount: list.reduce((s, x) => s + (x.totalAmount || 0), 0),
      }))
      .sort((a, b) => a.companyCode.localeCompare(b.companyCode));
  }, [vouchers]);

  useEffect(() => {
    setOpenCompanies(new Set(companies.map(c => c.companyCode)));
  }, [companies]);

  const toggleCompany = (key: string) => {
    setOpenCompanies(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const toggleVoucher = (key: string) => {
    setOpenVouchers(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  if (vouchers.length === 0) {
    return (
      <p className={styles.emptyCell} data-testid={tid('empty')}>
        Chưa có chứng từ được tạo
      </p>
    );
  }

  return (
    <div className={styles.postingSummary} data-testid={tid('root')}>
      <p className={styles.hint}>
        Đã tạo <strong>{vouchers.length.toLocaleString('vi-VN')}</strong> chứng từ
        — nhóm theo <strong>Đơn vị</strong> · ngày · mã CT · số tiền.
        Click mã CT → slideout View · «Mở trang đầy đủ» mở tab workspace (form IMP vẫn giữ).
      </p>
      <div className={styles.postingSummaryMeta}>
        <span>CT: <strong>{vouchers.length.toLocaleString('vi-VN')}</strong></span>
        <span>
          Tổng tiền:{' '}
          <strong>{money(vouchers.reduce((s, v) => s + (v.totalAmount || 0), 0))}</strong>
        </span>
        <span>Đơn vị: <strong>{companies.length}</strong></span>
      </div>

      <div className={styles.tableScroll}>
        {companies.map(cg => {
          const open = openCompanies.has(cg.companyCode);
          return (
            <div key={cg.companyCode} className={styles.postingGroup} data-testid={tid(`co-${cg.companyCode}`)}>
              <button
                type="button"
                className={styles.postingGroupHeader}
                onClick={() => toggleCompany(cg.companyCode)}
                aria-expanded={open}
              >
                <span className={styles.postingGroupToggle}>{open ? '▾' : '▸'}</span>
                <span className={styles.postingGroupTitle}>
                  <strong>{cg.companyCode}</strong>
                </span>
                <span className={styles.postingGroupStats}>
                  {cg.vouchers.length} CT · {money(cg.totalAmount)}
                </span>
              </button>

              {open && (
                <div className={confirmStyles.successVoucherList}>
                  {cg.vouchers.map(v => {
                    const vk = v.groupKey || v.voucherCode;
                    const vOpen = openVouchers.has(vk);
                    return (
                      <div key={vk} className={confirmStyles.successVoucherCard}>
                        <div className={confirmStyles.successVoucherHead}>
                          <button
                            type="button"
                            className={styles.linkBtn}
                            onClick={() => toggleVoucher(vk)}
                          >
                            {vOpen ? '▾' : '▸'} {v.voucherDate || '—'} · {v.voucherKindLabel}
                          </button>
                          <button
                            type="button"
                            className={confirmStyles.linkBtn}
                            onClick={() => onOpenVoucher?.(v)}
                            title="Xem chứng từ (slideout)"
                          >
                            {v.voucherCode}
                          </button>
                          <span>{v.postingReasonCode || '—'}</span>
                          <strong>{money(v.totalAmount)}</strong>
                        </div>
                        <div className={styles.hint} style={{ padding: '0 8px 6px' }}>
                          IMP: <strong>{v.sourceImportCode}</strong>
                          {' · '}id: <code>{v.sourceImportId}</code>
                          {' · '}{v.lineCount} dòng gốc
                        </div>
                        {vOpen && (
                          <table className={styles.reasonTable} data-testid={tid(`src-${vk}`)}>
                            <thead>
                              <tr>
                                <th>Ngày</th>
                                <th>Mã GD / FT</th>
                                <th>Nội dung</th>
                                <th>Đối tượng</th>
                                <th>Lô</th>
                                <th>Path gốc</th>
                                <th style={{ textAlign: 'right' }}>Tiền</th>
                              </tr>
                            </thead>
                            <tbody>
                              {v.sourceLines.map(s => (
                                <tr key={`${s.statementLineId}-${s.batchLineId || ''}`}>
                                  <td>{s.transactionDate || '—'}</td>
                                  <td>{s.batchFtNumber || s.referenceCode || '—'}</td>
                                  <td>{s.description || '—'}</td>
                                  <td>{s.counterpartyName || '—'}</td>
                                  <td>{s.batchRef || '—'}</td>
                                  <td className={styles.pathCell} title={s.importReference || undefined}>
                                    {s.importReference || '—'}
                                  </td>
                                  <td style={{ textAlign: 'right', fontWeight: 600 }}>{money(s.amount)}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
