import React, { useState } from 'react';
import type { BankStatementImportPostingSummary } from '../../../../../services/kt/bankStatementImportModels';
import styles from './StepClassifyImp.module.css';

type Props = {
  summary: BankStatementImportPostingSummary | null;
  loading?: boolean;
  error?: string | null;
  testIdPrefix: string;
  onReload?: () => void;
};

function money(n: number): string {
  return (n ?? 0).toLocaleString('vi-VN');
}

/**
 * Tab Định khoản — master Đơn vị cơ sở / detail ĐK Nợ·Có·tiền (từ BE posting-summary).
 */
export const ClassifyPostingSummaryPanel: React.FC<Props> = ({
  summary,
  loading,
  error,
  testIdPrefix,
  onReload,
}) => {
  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const [openCodes, setOpenCodes] = useState<Set<string>>(() => new Set());

  const toggle = (key: string) => {
    setOpenCodes(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  // Mặc định mở tất cả khi summary đổi
  React.useEffect(() => {
    if (!summary?.companies?.length) {
      setOpenCodes(new Set());
      return;
    }
    setOpenCodes(new Set(summary.companies.map((c, i) => c.companyCode || `__empty_${i}`)));
  }, [summary]);

  if (loading) {
    return <p className={styles.hint} data-testid={tid('loading')}>Đang tải tổng hợp định khoản…</p>;
  }

  if (error) {
    return (
      <div data-testid={tid('error')}>
        <p className={styles.error}>{error}</p>
        {onReload && (
          <button type="button" className={styles.filterBtn} onClick={onReload}>
            Thử lại
          </button>
        )}
      </div>
    );
  }

  if (!summary || summary.companies.length === 0) {
    return (
      <p className={styles.emptyCell} data-testid={tid('empty')}>
        Chưa có giao dịch để tổng hợp định khoản
      </p>
    );
  }

  return (
    <div className={styles.postingSummary} data-testid={tid('root')}>
      <p className={styles.hint}>
        Chi tiết theo <strong>Đơn vị cơ sở</strong> → định khoản Nợ/Có và số tiền
        (theo chứng từ đã lưu trên server).{' '}
        {onReload && (
          <button type="button" className={styles.linkBtn} onClick={onReload} data-testid={tid('reload')}>
            Tải lại
          </button>
        )}
      </p>
      <div className={styles.postingSummaryMeta}>
        <span>Dòng: <strong>{summary.totalLineCount.toLocaleString('vi-VN')}</strong></span>
        <span>Tổng tiền: <strong>{money(summary.totalAmount)}</strong></span>
        <span>Đơn vị: <strong>{summary.companies.length}</strong></span>
      </div>

      <div className={styles.tableScroll}>
        {summary.companies.map((co, idx) => {
          const key = co.companyCode || `__empty_${idx}`;
          const open = openCodes.has(key);
          return (
            <div key={key} className={styles.postingGroup} data-testid={tid(`company-${key}`)}>
              <button
                type="button"
                className={styles.postingGroupHeader}
                onClick={() => toggle(key)}
                aria-expanded={open}
              >
                <span className={styles.postingGroupToggle}>{open ? '▾' : '▸'}</span>
                <span className={styles.postingGroupTitle}>
                  {co.companyCode
                    ? <><strong>{co.companyCode}</strong> — {co.companyName}</>
                    : <strong>{co.companyName}</strong>}
                </span>
                <span className={styles.postingGroupStats}>
                  {co.lineCount.toLocaleString('vi-VN')} dòng · {money(co.totalAmount)}
                </span>
              </button>

              {open && (
                <table className={styles.reasonTable}>
                  <thead>
                    <tr>
                      <th>Mã ĐK</th>
                      <th>Tên định khoản</th>
                      <th>TK Nợ</th>
                      <th>TK Có</th>
                      <th style={{ textAlign: 'right' }}>Số dòng</th>
                      <th style={{ textAlign: 'right' }}>Tiền</th>
                      <th style={{ textAlign: 'right' }}>Thu</th>
                      <th style={{ textAlign: 'right' }}>Chi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {co.postings.length === 0 ? (
                      <tr>
                        <td colSpan={8} className={styles.emptyCell}>Không có định khoản</td>
                      </tr>
                    ) : (
                      co.postings.map(p => (
                        <tr key={`${key}-${p.postingReasonCode || '_none'}`}>
                          <td>{p.postingReasonCode || '—'}</td>
                          <td>{p.postingReasonName}</td>
                          <td>{p.debitAccountCode || '—'}</td>
                          <td>{p.creditAccountCode || '—'}</td>
                          <td style={{ textAlign: 'right' }}>{p.lineCount.toLocaleString('vi-VN')}</td>
                          <td style={{ textAlign: 'right', fontWeight: 600 }}>{money(p.amount)}</td>
                          <td style={{ textAlign: 'right' }}>{money(p.creditAmount)}</td>
                          <td style={{ textAlign: 'right' }}>{money(p.debitAmount)}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
