type ClassifyTab = 'thu' | 'chi' | 'map-lo' | 'dinh-khoan';

interface Props {
  voucher: BankStatementImportVoucher;
  /** Lưu map → next step (mức XL 3). */
  onSaved: (voucher: BankStatementImportVoucher) => void;
  /** Fill thông tin — cập nhật voucher, ở lại bước Review map. */
  onFilled?: (voucher: BankStatementImportVoucher) => void;
  onBack: () => void;
}

function isSkipped(l: BankStatementImportStatementLine): boolean {
  return (l.lineStatus || '').toLowerCase() === 'skipped';
}

/** Giao dịch lỗi Review map — 3 tiêu chí (user). */
const NON_EXPENSE_COST_CODES = new Set(['TT_CONG_NO_NCC', 'CHUYEN_NOI_BO']);

function isExpenseClassifyLine(l: BankStatementImportStatementLine): boolean {
  const cost = (l.costCode || '').trim().toUpperCase();
  if (!cost) return false;
  return !NON_EXPENSE_COST_CODES.has(cost);
}

function isClassifyMapError(l: BankStatementImportStatementLine): boolean {
  if (isSkipped(l)) return false;
  const missingContra = !(l.contraAccountCode || '').trim();
  const missingCompany = !(l.companyCode || '').trim();
  const missingCustomer = !(l.customerCode || '').trim();
  // Không thuộc chi phí nhưng thiếu thông tin khách hàng
  const nonExpenseMissingCustomer = !isExpenseClassifyLine(l) && missingCustomer;
  return missingContra || missingCompany || nonExpenseMissingCustomer;
}

type ClassifyLineFilter = 'all' | 'error' | 'batch';

function isThuLine(l: BankStatementImportStatementLine): boolean {
  if (isSkipped(l)) return false;
  if ((l.creditAmount ?? 0) > 0) return true;
  if ((l.debitAmount ?? 0) > 0) return false;
  if (l.suggestedVoucherType === 'bao_co') return true;
  if (l.suggestedVoucherType === 'bao_no') return false;
  return (l.amount ?? 0) > 0;
}

function isChiLine(l: BankStatementImportStatementLine): boolean {
  if (isSkipped(l)) return false;
  if ((l.debitAmount ?? 0) > 0) return true;
  if ((l.creditAmount ?? 0) > 0) return false;
  if (l.suggestedVoucherType === 'bao_no') return true;
  if (l.suggestedVoucherType === 'bao_co') return false;
  return (l.amount ?? 0) > 0 && !(l.creditAmount);
}

function withDefaultCompany(
  lines: BankStatementImportStatementLine[],
  voucherCompany: string,
): BankStatementImportStatementLine[] {
  const fallback = (getActiveCompanyCode() || voucherCompany || '').trim();
  if (!fallback) return lines;
  return lines.map(l => ({
    ...l,
    companyCode: (l.companyCode || '').trim() || fallback,
  }));
}

function withDefaultCompanyBatch(
  lines: BankStatementImportBatchLine[],
  voucherCompany: string,
): BankStatementImportBatchLine[] {
  const fallback = (getActiveCompanyCode() || voucherCompany || '').trim();
  if (!fallback) return lines;
  return lines.map(l => ({
    ...l,
    companyCode: (l.companyCode || '').trim() || fallback,
  }));
}

function isBatchClassifyError(b: BankStatementImportBatchLine): boolean {
  if ((b.lineStatus || 'Draft').toLowerCase() === 'skipped') return false;
  if (b.errorCode) return true;
  if (!(b.companyCode || '').trim()) return true;
  if (!(b.postingReasonCode || '').trim()) return true;
  if (!(b.contraAccountCode || '').trim()) return true;
  if (!(b.customerCode || '').trim()) return true;
  return false;
}

function batchLineDirtyKey(l: BankStatementImportBatchLine): string {
  return [
    l.id,
    l.customerCode ?? '',
    l.customerName ?? '',
    l.postingReasonCode ?? '',
    l.contraAccountCode ?? '',
    l.costCode ?? '',
    l.companyCode ?? '',
    l.lineStatus || 'Draft',
  ].join('|');
}

/**
 * Map line IMP → row đối soát — gắn postingCategory giống bước import
 * để BatchReconcilePanel skip giao dịch chi phí (ShowOnImportFilter).
 */
function statementToImportRow(l: BankStatementImportStatementLine): BankStatementImportRow {
  const detected = detectPostingCategory(
    l.description ?? '',
    l.customerName ?? l.counterpartyName ?? '',
  );
  const cost = (l.costCode ?? '').trim().toUpperCase();
  const skipCodes = getExpenseImportFilterCodes();
  const costIsExpenseFilter = Boolean(cost && skipCodes.has(cost));
  const costLabel = costIsExpenseFilter
    ? (getExpenseImportFilterCategories().find(c => c.code === cost)?.label ?? cost)
    : undefined;

  return {
    rowIndex: l.rowIndex,
    transactionDate: l.transactionDate,
    referenceCode: l.referenceCode,
    amount: l.amount,
    debitAmount: l.debitAmount,
    creditAmount: l.creditAmount,
    feeAmount: l.feeAmount,
    taxAmount: l.taxAmount,
    counterpartyName: l.counterpartyName,
    description: l.description,
    bankAccountCode: l.bankAccountCode,
    partnerBankName: l.partnerBankName,
    importReference: l.importReference,
    expenseNote: l.expenseNote,
    suggestedVoucherType: l.suggestedVoucherType as 'bao_no' | 'bao_co' | undefined,
    detectedBatchRefs: l.detectedBatchRefs,
    customerCode: l.customerCode,
    postingCategoryCode: costIsExpenseFilter ? cost : detected.code,
    postingCategoryLabel: costIsExpenseFilter ? costLabel : detected.label,
  };
}

function batchLineToDetail(l: BankStatementImportVoucher['batchLines'][number]): BatchDetailLine {
  return {
    lineIndex: l.lineIndex,
    beneficiaryName: l.beneficiaryName || '',
    accountNumber: l.accountNumber,
    bankName: l.bankName,
    amount: l.amount,
    ftNumber: l.ftNumber,
    description: l.description,
    status: l.status,
    sheetDate: l.sheetDate,
    batchRef: l.batchRef,
    staffNote: l.staffNote,
    companyCode: l.companyCode,
    sourcePath: l.sourcePath,
  };
}

const StepClassifyImp: React.FC<Props> = ({ voucher, onSaved, onFilled, onBack }) => {
  const dispatch = useAppDispatch();
  const shellRef = useRef<HTMLDivElement>(null);
  useVoucherFormShellHeight(shellRef);

  const [lines, setLines] = useState<BankStatementImportStatementLine[]>(() =>
    withDefaultCompany(voucher.statementLines, voucher.companyCode),
  );
  const [batchLines, setBatchLines] = useState<BankStatementImportBatchLine[]>(() =>
    withDefaultCompanyBatch(voucher.batchLines ?? [], voucher.companyCode),
  );
  const [accountCode, setAccountCode] = useState(voucher.accountCode || '1121');
  const [bankAccountName, setBankAccountName] = useState('');
  const [tab, setTab] = useState<ClassifyTab>('chi');
  const [lineFilter, setLineFilter] = useState<ClassifyLineFilter>('all');
  const [saving, setSaving] = useState(false);
  const [filling, setFilling] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [allReasons, setAllReasons] = useState<PostingReasonInitItem[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<ListPageSize>(DEFAULT_PAGE_SIZE);
  const [companyByCode, setCompanyByCode] = useState<Map<string, CompanyCodeLookupItem>>(
    () => new Map(),
  );
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const [focusedLineId, setFocusedLineId] = useState<string | null>(null);
  const [skipConfirm, setSkipConfirm] = useState<{ ids: string[]; message: string } | null>(null);
  const [fillDirtyConfirm, setFillDirtyConfirm] = useState(false);
  const [reconcileLinks, setReconcileLinks] = useState<ReconcileStatementBatchLink[]>(() =>
    (voucher.links ?? []).map(l => ({
      statementRowIndex: l.statementRowIndex,
      statementImportReference: l.statementImportReference,
      statementReferenceCode: l.statementReferenceCode,
      batchRef: l.batchRef,
    })),
  );
  const [customerMapOpen, setCustomerMapOpen] = useState(false);
  const [customerMapLoading, setCustomerMapLoading] = useState(false);
  const [customerMapApplying, setCustomerMapApplying] = useState(false);
  const [customerMapError, setCustomerMapError] = useState<string | null>(null);
  const [customerMapPreview, setCustomerMapPreview] = useState<BankStatementCustomerBankMapPreview | null>(null);
  const [customerMapPending, setCustomerMapPending] = useState<{
    lineId: string;
    customerCode: string;
    customerName: string;
    bankAccountNumber: string;
    bankName?: string;
  } | null>(null);
  const [postingSummary, setPostingSummary] = useState<BankStatementImportPostingSummary | null>(null);
  const [postingSummaryLoading, setPostingSummaryLoading] = useState(false);
  const [postingSummaryError, setPostingSummaryError] = useState<string | null>(null);

  /** Snapshot server — dirty = khác baseline (chưa lưu). */
  const baselineKey = useMemo(() => {
    const baseLines = withDefaultCompany(voucher.statementLines, voucher.companyCode);
    const linesKey = baseLines.map(l => ([
      l.id,
      l.customerCode ?? '',
      l.customerName ?? '',
      l.postingReasonCode ?? '',
      l.contraAccountCode ?? '',
      l.costCode ?? '',
      l.companyCode ?? '',
      l.lineStatus || 'Draft',
    ].join('|'))).join(';');
    const batchKey = withDefaultCompanyBatch(voucher.batchLines ?? [], voucher.companyCode)
      .map(batchLineDirtyKey)
      .join(';');
    const linksKey = (voucher.links ?? []).map(l =>
      `${l.statementRowIndex}|${l.batchRef}|${l.statementImportReference ?? ''}|${l.statementReferenceCode ?? ''}`,
    ).join(';');
    return `${voucher.accountCode || '1121'}::${linesKey}::${batchKey}::${linksKey}`;
  }, [voucher]);

  const currentKey = useMemo(() => {
    const linesKey = lines.map(l => ([
      l.id,
      l.customerCode ?? '',
      l.customerName ?? '',
      l.postingReasonCode ?? '',
      l.contraAccountCode ?? '',
      l.costCode ?? '',
      l.companyCode ?? '',
      l.lineStatus || 'Draft',
    ].join('|'))).join(';');
    const batchKey = batchLines.map(batchLineDirtyKey).join(';');
    const linksKey = reconcileLinks.map(l =>
      `${l.statementRowIndex}|${l.batchRef}|${l.statementImportReference ?? ''}|${l.statementReferenceCode ?? ''}`,
    ).join(';');
    return `${accountCode}::${linesKey}::${batchKey}::${linksKey}`;
  }, [accountCode, lines, batchLines, reconcileLinks]);

  const isDirty = currentKey !== baselineKey;

  useEffect(() => {
    setLines(withDefaultCompany(voucher.statementLines, voucher.companyCode));
    setBatchLines(withDefaultCompanyBatch(voucher.batchLines ?? [], voucher.companyCode));
    setAccountCode(voucher.accountCode || '1121');
    setReconcileLinks((voucher.links ?? []).map(l => ({
      statementRowIndex: l.statementRowIndex,
      statementImportReference: l.statementImportReference,
      statementReferenceCode: l.statementReferenceCode,
      batchRef: l.batchRef,
    })));
    setSelectedIds(new Set());
    setFocusedLineId(null);
  }, [voucher]);

  /** Links hiệu lực: DB/map + GD phụ khớp tiền cùng ngày (parity Map GD/Lô). */
  const effectiveLinks = useMemo(
    () => expandLinksWithAmountCompanions(lines, reconcileLinks, batchLines),
    [lines, reconcileLinks, batchLines],
  );

  const refsByLineId = useMemo(() => {
    const map = new Map<string, string[]>();
    for (const line of lines) {
      const resolved = resolveLinkedBatchRefsForStatement(line, effectiveLinks, batchLines);
      if (resolved.length > 0) map.set(line.id, resolved);
    }
    return map;
  }, [lines, effectiveLinks, batchLines]);

  const isBatchLinkedLine = useCallback((l: BankStatementImportStatementLine) => {
    if (isSkipped(l)) return false;
    return (refsByLineId.get(l.id) ?? []).length > 0;
  }, [refsByLineId]);

  const isClassifyMapErrorLine = useCallback((l: BankStatementImportStatementLine) => {
    if (isSkipped(l)) return false;
    const refs = refsByLineId.get(l.id) ?? [];
    if (refs.length > 0) {
      const details = collectBatchLinesForRefs(refs, batchLines);
      if (details.length === 0) return true;
      return details.some(isBatchClassifyError);
    }
    return isClassifyMapError(l);
  }, [refsByLineId, batchLines]);

  const thuLines = useMemo(() => lines.filter(isThuLine), [lines]);
  const chiLines = useMemo(() => lines.filter(isChiLine), [lines]);
  const hasThu = thuLines.length > 0;
  const hasBatchMap = (voucher.batchLines?.length ?? 0) > 0 || (voucher.links?.length ?? 0) > 0;

  const classifyTabs = useMemo(() => {
    const tabs: { id: ClassifyTab; label: string }[] = [];
    if (hasThu) tabs.push({ id: 'thu', label: 'Thu' });
    tabs.push({ id: 'chi', label: 'Chi' });
    if (hasBatchMap) tabs.push({ id: 'map-lo', label: 'Map GD / Lô' });
    tabs.push({ id: 'dinh-khoan', label: 'Định khoản' });
    return tabs;
  }, [hasThu, hasBatchMap]);

  useEffect(() => {
    if (tab === 'thu' && !hasThu) setTab('chi');
    if (tab === 'map-lo' && !hasBatchMap) setTab('chi');
  }, [tab, hasThu, hasBatchMap]);

  useEffect(() => {
    setPage(1);
    setSelectedIds(new Set());
  }, [tab]);

  useEffect(() => {
    setPage(1);
  }, [lineFilter]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        /**
         * IMP cần đủ ĐK bank + nghiệp vụ dùng chung (Allowed = phieu-thu,phieu-chi / DocumentType KC).
         * BE `IsAllowed` loại shared khi truyền voucherTypeCode=phieu-thu|phieu-chi — nên không truyền type.
         * isCash=false → bank (112x) + system/general (không 111/112).
         */
        const rules = await ktService.getPostingReasonRules({ isCash: false, pageSize: 2000 });
        if (cancelled) return;
        setAllReasons((rules ?? []).map(mapPostingReasonRuleToInitItem));
      } catch {
        if (!cancelled) setAllReasons([]);
      }
    };
    const t = window.setTimeout(load, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, []);

  /** IMP: full ĐK list (thu+chi). Không filter theo TK NH — ĐK chi phí (6427/3311…) không chứa 1121. */
  const classifyReasons = useMemo(
    () => dedupePostingReasonRules(allReasons),
    [allReasons],
  );

  const postingReasonSearchConfig = useMemo(
    () => createPostingReasonSearchConfig(classifyReasons),
    [classifyReasons],
  );

  const postingReasonByCode = useMemo(
    () => new Map(classifyReasons.map(r => [r.code, r])),
    [classifyReasons],
  );

  const postingReasonByExpenseCode = useMemo(
    () => buildPostingReasonByExpenseCode(classifyReasons),
    [classifyReasons],
  );

  const costCodeSearchConfig = useMemo(() => createCostCodeSearchConfig(), []);

  const companyCodeSearchConfig = useMemo(
    () => createCompanyCodeSearchConfig([voucher.companyCode]),
    [voucher.companyCode],
  );

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      loadCompanyCodeMap([voucher.companyCode]).then(map => {
        if (!cancelled) setCompanyByCode(map);
      });
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [voucher.companyCode]);

  const accountSearchOptions = useAccountSearchAsOfDate(undefined);
  const accountSearchConfig = useMemo(
    () => createAccountSearchConfig(accountSearchOptions),
    [accountSearchOptions],
  );

  const activeLines = useMemo(() => {
    const base = tab === 'thu' ? thuLines : tab === 'chi' ? chiLines : [];
    let filtered = base;
    if (lineFilter === 'error') filtered = base.filter(isClassifyMapErrorLine);
    else if (lineFilter === 'batch') filtered = base.filter(isBatchLinkedLine);
    // GD chung lô đứng cạnh nhau → grid group Master/Detail đúng (vd 2 GD → 1 lô)
    return clusterStatementLinesByBatchLink(filtered, effectiveLinks, batchLines);
  }, [
    tab, thuLines, chiLines, lineFilter,
    isClassifyMapErrorLine, isBatchLinkedLine, effectiveLinks, batchLines,
  ]);

  const lineFilterCounts = useMemo(() => {
    const base = tab === 'thu' ? thuLines : tab === 'chi' ? chiLines : [];
    return {
      all: base.length,
      error: base.filter(isClassifyMapErrorLine).length,
      batch: base.filter(isBatchLinkedLine).length,
    };
  }, [tab, thuLines, chiLines, isClassifyMapErrorLine, isBatchLinkedLine]);

  const activeTotal = tab === 'dinh-khoan'
    ? (postingSummary?.companies.length ?? 0)
    : activeLines.length;

  /** Phân trang — mở rộng biên trang để không cắt cụm GD cùng lô. */
  const pagedWindow = useMemo(() => {
    let start = (page - 1) * pageSize;
    let end = Math.min(activeLines.length, start + pageSize);
    if (activeLines.length === 0 || start >= activeLines.length) {
      return { start: 0, lines: [] as typeof activeLines };
    }

    const normsOf = (l: (typeof activeLines)[number]) => {
      const set = new Set<string>();
      for (const ref of (refsByLineId.get(l.id) ?? [])) {
        const n = normalizeBulkRef(ref);
        if (n) set.add(n);
      }
      return set;
    };
    const shares = (a: (typeof activeLines)[number], b: (typeof activeLines)[number]) => {
      const na = normsOf(a);
      if (na.size === 0) return false;
      for (const n of normsOf(b)) {
        if (na.has(n)) return true;
      }
      return false;
    };

    while (start > 0 && shares(activeLines[start - 1], activeLines[start])) start -= 1;
    while (end < activeLines.length && shares(activeLines[end - 1], activeLines[end])) end += 1;

    return { start, lines: activeLines.slice(start, end) };
  }, [activeLines, page, pageSize, refsByLineId]);

  const pagedLines = pagedWindow.lines;
  const rowOffset = pagedWindow.start;

  const loadPostingSummary = useCallback(async () => {
    setPostingSummaryLoading(true);
    setPostingSummaryError(null);
    try {
      const data = await bankStatementImportService.getPostingSummary(voucher.id);
      setPostingSummary(data);
    } catch (err) {
      setPostingSummary(null);
      setPostingSummaryError(getApiErrorMessage(err, 'Không tải được tổng hợp định khoản'));
    } finally {
      setPostingSummaryLoading(false);
    }
  }, [voucher.id]);

  useEffect(() => {
    if (tab !== 'dinh-khoan') return;
    let cancelled = false;
    const t = window.setTimeout(() => {
      if (!cancelled) void loadPostingSummary();
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [tab, loadPostingSummary, voucher.id, voucher.statementLines]);

  useEffect(() => {
    const totalPages = Math.max(1, Math.ceil(activeTotal / pageSize));
    if (page > totalPages) setPage(totalPages);
  }, [activeTotal, page, pageSize]);

  const totals = useMemo(() => {
    let credit = 0;
    let debit = 0;
    let fee = 0;
    let tax = 0;
    let skipped = 0;
    for (const l of lines) {
      if (isSkipped(l)) {
        skipped += 1;
        continue;
      }
      credit += l.creditAmount ?? 0;
      debit += l.debitAmount ?? 0;
      fee += l.feeAmount ?? 0;
      tax += l.taxAmount ?? 0;
    }
    return { credit, debit, fee, tax, count: lines.length - skipped, skipped };
  }, [lines]);

  const showFeeTaxColumns = totals.fee > 0 || totals.tax > 0;

  const CLASSIFY_SYNC_KEYS = [
    'customerCode', 'customerName', 'postingReasonCode',
    'contraAccountCode', 'costCode', 'companyCode',
  ] as const;

  const pickClassifySync = useCallback((
    patchRow: Partial<BankStatementImportStatementLine> | Partial<BankStatementImportBatchLine>,
  ) => {
    const out: Partial<BankStatementImportStatementLine & BankStatementImportBatchLine> = {};
    for (const k of CLASSIFY_SYNC_KEYS) {
      if (Object.prototype.hasOwnProperty.call(patchRow, k)) {
        (out as Record<string, unknown>)[k] = (patchRow as Record<string, unknown>)[k];
      }
    }
    return out;
  }, []);

  /** Patch sao kê + đồng bộ classify sang dòng lô đã link. */
  const patch = useCallback((id: string, patchRow: Partial<BankStatementImportStatementLine>) => {
    const sync = pickClassifySync(patchRow);
    setLines(prev => prev.map(l => (l.id === id ? { ...l, ...patchRow } : l)));
    if (Object.keys(sync).length === 0) return;
    const refs = new Set(
      (refsByLineId.get(id) ?? []).map(r => normalizeBulkRef(r)).filter(Boolean),
    );
    if (refs.size === 0) return;
    setBatchLines(prev => prev.map(b => {
      const n = normalizeBulkRef(b.batchRef || '');
      if (!n || !refs.has(n)) return b;
      if (String(b.lineStatus || '').toLowerCase() === 'skipped') return b;
      return { ...b, ...sync };
    }));
  }, [pickClassifySync, refsByLineId]);

  /** Patch dòng lô + đồng bộ classify sang GD sao kê đã link. */
  const patchBatch = useCallback((id: string, patchRow: Partial<BankStatementImportBatchLine>) => {
    const sync = pickClassifySync(patchRow);
    let batchRefNorm = '';
    setBatchLines(prev => prev.map(l => {
      if (l.id !== id) return l;
      batchRefNorm = normalizeBulkRef(l.batchRef || '');
      return { ...l, ...patchRow };
    }));
    if (Object.keys(sync).length === 0 || !batchRefNorm) return;
    setLines(prev => prev.map(l => {
      if (isSkipped(l)) return l;
      const refs = (refsByLineId.get(l.id) ?? []).map(r => normalizeBulkRef(r));
      if (!refs.includes(batchRefNorm)) return l;
      return { ...l, ...sync };
    }));
  }, [pickClassifySync, refsByLineId]);

  const handleCustomerSelect = useCallback(async (
    line: BankStatementImportStatementLine,
    customer: { code: string; name: string },
  ) => {
    // Always patch line first so SearchInput (controlled) updates after select/create.
    patch(line.id, { customerCode: customer.code, customerName: customer.name });

    const bank = (line.bankAccountCode || '').trim();
    if (!bank) return;

    setCustomerMapPending({
      lineId: line.id,
      customerCode: customer.code,
      customerName: customer.name,
      bankAccountNumber: bank,
      bankName: line.partnerBankName || undefined,
    });
    setCustomerMapPreview(null);
    setCustomerMapError(null);
    setCustomerMapOpen(true);
    setCustomerMapLoading(true);
    try {
      const preview = await bankStatementImportService.getCustomerBankMapPreview(voucher.id, {
        customerCode: customer.code,
        bankAccountNumber: bank,
      });
      setCustomerMapPreview({
        ...preview,
        bankName: preview.bankName || line.partnerBankName || null,
      });
    } catch (err) {
      setCustomerMapError(getApiErrorMessage(err, 'Không tải được thông tin map đối tượng'));
    } finally {
      setCustomerMapLoading(false);
    }
  }, [patch, voucher.id]);

  const closeCustomerMap = useCallback(() => {
    if (customerMapApplying) return;
    setCustomerMapOpen(false);
    setCustomerMapPending(null);
    setCustomerMapPreview(null);
    setCustomerMapError(null);
  }, [customerMapApplying]);

  const applyCustomerMap = useCallback(async (mode: ApplyCustomerBankMapMode) => {
    const pending = customerMapPending;
    if (!pending) return;

    if (mode === 'lineOnly') {
      patch(pending.lineId, {
        customerCode: pending.customerCode,
        customerName: pending.customerName,
      });
      closeCustomerMap();
      return;
    }

    setCustomerMapApplying(true);
    setCustomerMapError(null);
    try {
      const result = await bankStatementImportService.applyCustomerBankMap(voucher.id, {
        mode,
        customerCode: pending.customerCode,
        customerName: pending.customerName,
        statementLineId: pending.lineId,
        bankAccountNumber: pending.bankAccountNumber,
        bankName: pending.bankName,
      });
      const ids = new Set((result.updatedStatementLineIds ?? []).map(String));
      setLines(prev => prev.map(l => {
        if (!ids.has(l.id) && l.id !== pending.lineId) return l;
        return {
          ...l,
          customerCode: pending.customerCode,
          customerName: pending.customerName,
        };
      }));
      // Đồng bộ ĐT sang dòng lô đã link
      setBatchLines(prev => {
        const linkedNorms = new Set<string>();
        for (const l of lines) {
          if (!ids.has(l.id) && l.id !== pending.lineId) continue;
          for (const ref of (refsByLineId.get(l.id) ?? [])) {
            const n = normalizeBulkRef(ref);
            if (n) linkedNorms.add(n);
          }
        }
        if (linkedNorms.size === 0) return prev;
        return prev.map(b => {
          const n = normalizeBulkRef(b.batchRef || '');
          if (!n || !linkedNorms.has(n)) return b;
          if (String(b.lineStatus || '').toLowerCase() === 'skipped') return b;
          return {
            ...b,
            customerCode: pending.customerCode,
            customerName: pending.customerName,
          };
        });
      });
      dispatchAppToast(dispatch, {
        type: 'success',
        message: mode === 'catalogAndVoucher'
          ? `Đã ${result.catalogUpdated ? 'thêm STK vào danh mục và ' : ''}map ${result.updatedLineCount} giao dịch`
          : `Đã map ${result.updatedLineCount} giao dịch cùng STK trên chứng từ`,
      });
      setCustomerMapOpen(false);
      setCustomerMapPending(null);
      setCustomerMapPreview(null);
    } catch (err) {
      setCustomerMapError(getApiErrorMessage(err, 'Không áp dụng được map đối tượng'));
    } finally {
      setCustomerMapApplying(false);
    }
  }, [customerMapPending, closeCustomerMap, patch, voucher.id, dispatch, lines, refsByLineId]);

  const toggleSelect = useCallback((id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const toggleSelectAllPage = useCallback((checked: boolean) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      for (const l of pagedLines) {
        if (checked) next.add(l.id);
        else next.delete(l.id);
      }
      return next;
    });
  }, [pagedLines]);

  const buildClassifyPayload = useCallback((advanceLevel: boolean) => ({
    accountCode: accountCode,
    advanceLevel,
    statementLines: lines.map(l => ({
      id: l.id,
      customerCode: l.customerCode,
      customerName: l.customerName,
      postingReasonCode: l.postingReasonCode,
      contraAccountCode: l.contraAccountCode,
      costCode: l.costCode,
      companyCode: l.companyCode,
      lineStatus: l.lineStatus || 'Draft',
    })),
    batchLines: batchLines.map(l => ({
      id: l.id,
      customerCode: l.customerCode,
      customerName: l.customerName,
      postingReasonCode: l.postingReasonCode,
      contraAccountCode: l.contraAccountCode,
      costCode: l.costCode,
      companyCode: l.companyCode,
      lineStatus: l.lineStatus || 'Draft',
    })),
    links: effectiveLinks.map(l => ({
      statementRowIndex: l.statementRowIndex,
      statementImportReference: l.statementImportReference,
      statementReferenceCode: l.statementReferenceCode,
      batchRef: l.batchRef,
    })),
  }), [accountCode, lines, batchLines, effectiveLinks]);

  const runRemapAndReload = useCallback(async () => {
    setFilling(true);
    setError(null);
    try {
      const result = await bankStatementImportService.remapClassify(voucher.id);
      const reloaded = await bankStatementImportService.getImportVoucher(voucher.id);
      dispatchAppToast(dispatch, {
        type: 'success',
        message: `Đã fill thông tin (${result.updatedLineCount}/${result.scannedLineCount} dòng) — đã tải lại chứng từ`,
      });
      onFilled?.(reloaded);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Không fill được thông tin'));
    } finally {
      setFilling(false);
    }
  }, [dispatch, onFilled, voucher.id]);

  const handleFillClick = () => {
    if (isDirty) {
      setFillDirtyConfirm(true);
      return;
    }
    void runRemapAndReload();
  };

  const handleFillSaveThenRemap = async () => {
    setFillDirtyConfirm(false);
    setFilling(true);
    setError(null);
    try {
      // Lưu phần hiện tại (không advance mức XL) rồi remap từ DB
      await bankStatementImportService.updateClassify(
        voucher.id,
        buildClassifyPayload(false),
      );
      const result = await bankStatementImportService.remapClassify(voucher.id);
      const reloaded = await bankStatementImportService.getImportVoucher(voucher.id);
      dispatchAppToast(dispatch, {
        type: 'success',
        message: `Đã lưu + fill (${result.updatedLineCount}/${result.scannedLineCount} dòng) — đã tải lại chứng từ`,
      });
      onFilled?.(reloaded);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Không lưu/fill được thông tin'));
    } finally {
      setFilling(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      const updated = await bankStatementImportService.updateClassify(
        voucher.id,
        buildClassifyPayload(true),
      );
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phân loại giao dịch' });
      onSaved(updated);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Không lưu được phân loại'));
    } finally {
      setSaving(false);
    }
  };

  const applySkip = useCallback((ids: string[]) => {
    if (ids.length === 0) return;
    const idSet = new Set(ids);
    const skipRefsNorm = new Set<string>();
    for (const l of lines) {
      if (!idSet.has(l.id)) continue;
      for (const ref of (refsByLineId.get(l.id) ?? [])) {
        const n = normalizeBulkRef(ref);
        if (n) skipRefsNorm.add(n);
      }
    }
    const keepRefsNorm = new Set<string>();
    for (const l of lines) {
      if (idSet.has(l.id) || isSkipped(l)) continue;
      for (const ref of (refsByLineId.get(l.id) ?? [])) {
        const n = normalizeBulkRef(ref);
        if (n) keepRefsNorm.add(n);
      }
    }
    setLines(prev => prev.map(l => (
      idSet.has(l.id) ? { ...l, lineStatus: 'Skipped' } : l
    )));
    setBatchLines(prev => prev.map(b => {
      const n = normalizeBulkRef(b.batchRef || '');
      if (!skipRefsNorm.has(n) || keepRefsNorm.has(n)) return b;
      return { ...b, lineStatus: 'Skipped' };
    }));
    setSelectedIds(new Set());
    setFocusedLineId(null);
    setSkipConfirm(null);
    dispatchAppToast(dispatch, {
      type: 'success',
      message: ids.length === 1 ? 'Đã bỏ qua 1 dòng sao kê' : `Đã bỏ qua ${ids.length} dòng sao kê`,
    });
  }, [dispatch, lines, refsByLineId]);

  const handleSkipClick = () => {
    if (selectedIds.size > 0) {
      setSkipConfirm({
        ids: [...selectedIds],
        message: `Bỏ qua ${selectedIds.size} dòng đã chọn? Dòng bỏ qua không tạo chứng từ.`,
      });
      return;
    }
    if (focusedLineId) {
      setSkipConfirm({
        ids: [focusedLineId],
        message: 'Bỏ qua giao dịch đang chọn? Dòng bỏ qua không tạo chứng từ.',
      });
      return;
    }
    dispatchAppToast(dispatch, {
      type: 'warning',
      message: 'Chọn ít nhất một dòng (checkbox) hoặc click vào một dòng trước khi bỏ qua.',
    });
  };

  const mapSaoke = useMemo(
    () => lines.filter(l => !isSkipped(l)).map(statementToImportRow),
    [lines],
  );

  const mapBatches = useMemo(() => {
    const file = new File([], 'imp-batch-from-db.xlsx');
    return [{ file, lines: batchLines.map(batchLineToDetail) }];
  }, [batchLines]);

  const initialLinks = useMemo(
    () => (voucher.links ?? []).map(l => ({
      statementRowIndex: l.statementRowIndex,
      statementImportReference: l.statementImportReference,
      statementReferenceCode: l.statementReferenceCode,
      batchRef: l.batchRef,
    })),
    [voucher.links],
  );

  const tid = (s: string) => `kt-import-sao-ke-classify-${s}`;
  const busy = saving || filling;

  return (
    <div
      ref={shellRef}
      className={`${df.pageVoucher} ${styles.root}`}
      data-voucher-form-shell
      data-testid="kt-import-sao-ke-step-classify"
    >
      <div className={df.pageFormHeader}>
        <div className={styles.toolbarRow}>
          <div className={styles.titleBlock}>
            <h1 className={styles.title}>
              Review map — {voucher.code}
              <span className={styles.levelPill}>Mức XL: {voucher.processingLevel}</span>
            </h1>
            <div className={styles.meta}>
              {voucher.importedByName || voucher.importedByEmployeeCode || '—'}
              {' · '}
              {voucher.monthCode}
              {' · '}
              Đơn vị {voucher.companyCode || getActiveCompanyCode() || '—'}
            </div>
          </div>
          <div className={styles.toolbarActions}>
            <Button variant="secondary" onClick={onBack} disabled={busy} data-testid={tid('back')}>
              Quay lại
            </Button>
            <Button
              variant="secondary"
              onClick={handleFillClick}
              loading={filling}
              disabled={busy}
              data-testid={tid('fill')}
              title="Tự động fill Đối tượng (tên/STK) · ĐK · mã CP · đơn vị — không chuyển bước tiếp"
            >
              Fill thông tin
            </Button>
            <Button variant="primary" onClick={handleSave} loading={saving} data-testid={tid('save')}>
              Lưu map → tiếp
            </Button>
          </div>
        </div>

        <div className={`${df.section} ${styles.headerFields}`}>
          <div className={styles.field} data-testid={tid('field-voucherCode')}>
            <span className={styles.label}>Số chứng từ</span>
            <div className={styles.roValue}>{voucher.code}</div>
          </div>
          <div className={styles.field} data-testid={tid('field-accountCode')}>
            <span className={styles.label}>TK nghiệp vụ (Nợ/Có)</span>
            <AccountSearchInput
              api={erpFinanceAccountSearchApi}
              config={accountSearchConfig}
              value={accountCode}
              primaryDisplay={formatAccountDisplay(accountCode, bankAccountName)}
              onChange={a => {
                setAccountCode(a.code);
                setBankAccountName(a.name);
              }}
              onClear={() => {
                setAccountCode('1121');
                setBankAccountName('');
              }}
              showLabel={false}
              showSecondaryInput={false}
              placeholder="TK nghiệp vụ (Nợ/Có)..."
            />
          </div>
        </div>

        <div className={styles.tabsWrap} data-testid={tid('tabs')}>
          <Tabs
            tabs={classifyTabs}
            activeTab={tab}
            onTabChange={id => setTab(id as ClassifyTab)}
            variant="underline"
            density="compact"
          />
        </div>

        {(tab === 'thu' || tab === 'chi') && (
          <div className={styles.filterBar} data-testid={tid('line-filter')}>
            <button
              type="button"
              className={`${styles.filterBtn} ${lineFilter === 'all' ? styles.filterActiveAll : ''}`}
              onClick={() => setLineFilter('all')}
              data-testid={tid('filter-all')}
            >
              Tất cả ({lineFilterCounts.all.toLocaleString('vi-VN')})
            </button>
            <button
              type="button"
              className={`${styles.filterBtn} ${lineFilter === 'batch' ? styles.filterActiveBatch : ''}`}
              onClick={() => setLineFilter('batch')}
              title="Chỉ GD đã map lô — kiểm tra group Sao kê chính / phụ + dòng lô"
              data-testid={tid('filter-batch')}
            >
              Giao dịch lô ({lineFilterCounts.batch.toLocaleString('vi-VN')})
            </button>
            <button
              type="button"
              className={`${styles.filterBtn} ${lineFilter === 'error' ? styles.filterActiveError : ''}`}
              onClick={() => setLineFilter('error')}
              title="Thiếu tài khoản đối ứng · thiếu đơn vị cơ sở · không thuộc chi phí nhưng thiếu khách hàng"
              data-testid={tid('filter-error')}
            >
              Giao dịch lỗi ({lineFilterCounts.error.toLocaleString('vi-VN')})
            </button>
            {lineFilter === 'batch' && (
              <span className={styles.filterHint}>
                GD đã link lô — mở expand để xem sao kê phụ (nếu có) và dòng lô cần điền
              </span>
            )}
            {lineFilter === 'error' && (
              <span className={styles.filterHint}>
                Thiếu tài khoản đối ứng · thiếu đơn vị cơ sở · giao dịch không thuộc chi phí nhưng thiếu thông tin khách hàng
              </span>
            )}
          </div>
        )}
      </div>

      <div className={`${df.pageFormScroll} ${styles.formScroll}`} data-testid={tid('form-scroll')}>
        {(tab === 'thu' || tab === 'chi') && (
          <ClassifyLinesGrid
            lines={pagedLines}
            batchLines={batchLines}
            links={effectiveLinks}
            rowOffset={rowOffset}
            showFeeTaxColumns={showFeeTaxColumns}
            postingReasonSearchConfig={postingReasonSearchConfig}
            postingReasonByCode={postingReasonByCode}
            postingReasonByExpenseCode={postingReasonByExpenseCode}
            costCodeSearchConfig={costCodeSearchConfig}
            companyCodeSearchConfig={companyCodeSearchConfig}
            companyByCode={companyByCode}
            selectedIds={selectedIds}
            focusedLineId={focusedLineId}
            onToggleSelect={toggleSelect}
            onToggleSelectAllPage={toggleSelectAllPage}
            onFocusLine={setFocusedLineId}
            onPatch={patch}
            onPatchBatch={patchBatch}
            onCustomerSelect={handleCustomerSelect}
            testIdPrefix={tid(tab)}
          />
        )}
        {tab === 'map-lo' && (
          <div className={styles.mapLoWrap} data-testid={tid('map-lo')}>
            <p className={styles.hint}>
              Map giao dịch ↔ lô — cùng filter bước import: ẩn GD chi phí (chip ShowOnImportFilter),
              chỉ hub thiếu đối tượng. Bấm «Lưu map» để ghi DB.
            </p>
            {mapBatches[0].lines.length === 0 ? (
              <div className={styles.emptyCell}>IMP chưa có dòng thanh toán lô</div>
            ) : (
              <BatchReconcilePanel
                saoke={mapSaoke}
                batches={mapBatches}
                initialLinks={initialLinks}
                onReconcileLinksChange={setReconcileLinks}
              />
            )}
          </div>
        )}
        {tab === 'dinh-khoan' && (
          <div className={`${df.section} ${styles.postingPanel} ${styles.linesFill}`} data-testid={tid('posting-panel')}>
            {isDirty && (
              <p className={styles.hint}>
                Có thay đổi chưa lưu trên lưới — tổng hợp bên dưới lấy từ chứng từ đã lưu.
                Bấm «Lưu map» hoặc «Fill» rồi tải lại để khớp bản đang sửa.
              </p>
            )}
            <ClassifyPostingSummaryPanel
              summary={postingSummary}
              loading={postingSummaryLoading}
              error={postingSummaryError}
              testIdPrefix={tid('posting-summary')}
              onReload={() => void loadPostingSummary()}
            />
          </div>
        )}
      </div>

      <div className={df.pageFormFooter} data-testid={tid('form-footer')}>
        <div className={df.footer}>
          <div className={styles.footerLeft}>
            {error && <div className={styles.error}>{error}</div>}
            <div className={styles.totals}>
              <span>Dòng: <strong>{totals.count}</strong></span>
              {totals.skipped > 0 && (
                <span>Bỏ qua: <strong>{totals.skipped}</strong></span>
              )}
              {hasThu && <span>Thu: <strong>{totals.credit.toLocaleString('vi-VN')}</strong></span>}
              <span>Chi: <strong>{totals.debit.toLocaleString('vi-VN')}</strong></span>
              {showFeeTaxColumns && (
                <>
                  <span>Phí: <strong>{totals.fee.toLocaleString('vi-VN')}</strong></span>
                  <span>Thuế: <strong>{totals.tax.toLocaleString('vi-VN')}</strong></span>
                </>
              )}
              {tab === 'dinh-khoan' && postingSummary ? (
                <span>
                  ĐK nhóm: <strong>{postingSummary.companies.length}</strong>
                  {' · '}
                  Tổng ĐK: <strong>{postingSummary.totalAmount.toLocaleString('vi-VN')}</strong>
                </span>
              ) : (
                <span>ĐK lookup: <strong>{classifyReasons.length}</strong></span>
              )}
            </div>
            {tab !== 'map-lo' && tab !== 'dinh-khoan' && (
              <VoucherListPagination
                testIdPrefix={tid('lines')}
                page={page}
                totalCount={activeTotal}
                pageSize={pageSize}
                onPageChange={setPage}
                onPageSizeChange={size => {
                  setPageSize(normalizeListPageSize(size));
                  setPage(1);
                }}
              />
            )}
          </div>
          <div className={styles.toolbarActions}>
            {(tab === 'thu' || tab === 'chi') && (
              <Button
                variant="secondary"
                onClick={handleSkipClick}
                disabled={busy}
                data-testid={tid('skip')}
              >
                Bỏ qua sao kê
                {selectedIds.size > 0 ? ` (${selectedIds.size})` : ''}
              </Button>
            )}
            <Button variant="secondary" onClick={onBack} disabled={busy} data-testid={tid('footer-back')}>
              Quay lại
            </Button>
            <Button variant="primary" onClick={handleSave} loading={saving} data-testid={tid('footer-save')}>
              Lưu phân loại → tiếp
            </Button>
          </div>
        </div>
      </div>

      {skipConfirm && (
        <div className={styles.confirmOverlay} role="presentation" onClick={() => setSkipConfirm(null)}>
          <div
            className={styles.confirmCard}
            role="dialog"
            aria-label="Xác nhận bỏ qua"
            onClick={e => e.stopPropagation()}
          >
            <div className={styles.confirmTitle}>Bỏ qua sao kê</div>
            <p className={styles.confirmMsg}>{skipConfirm.message}</p>
            <div className={styles.toolbarActions}>
              <Button variant="secondary" onClick={() => setSkipConfirm(null)}>Huỷ</Button>
              <Button
                variant="primary"
                onClick={() => applySkip(skipConfirm.ids)}
                data-testid={tid('skip-confirm')}
              >
                Xác nhận bỏ qua
              </Button>
            </div>
          </div>
        </div>
      )}

      {fillDirtyConfirm && (
        <div className={styles.confirmOverlay} role="presentation" onClick={() => setFillDirtyConfirm(false)}>
          <div
            className={styles.confirmCard}
            role="dialog"
            aria-label="Cảnh báo chưa lưu trước khi Fill"
            onClick={e => e.stopPropagation()}
            data-testid={tid('fill-dirty-confirm')}
          >
            <div className={styles.confirmTitle}>Chưa lưu thay đổi</div>
            <p className={styles.confirmMsg}>
              Phần đang chỉnh (đối tượng / ĐK / CP / đơn vị / map lô) chưa được lưu.
              Hãy lưu phần hiện tại trước khi Fill — nếu không, chỉnh sửa trên UI sẽ bị mất khi tải lại chứng từ.
            </p>
            <div className={styles.toolbarActions}>
              <Button
                variant="secondary"
                onClick={() => setFillDirtyConfirm(false)}
                data-testid={tid('fill-dirty-cancel')}
              >
                Huỷ
              </Button>
              <Button
                variant="primary"
                onClick={() => void handleFillSaveThenRemap()}
                loading={filling}
                data-testid={tid('fill-dirty-save-then')}
              >
                Lưu rồi Fill
              </Button>
            </div>
          </div>
        </div>
      )}

      <CustomerBankMapConfirmModal
        open={customerMapOpen}
        loading={customerMapLoading}
        applying={customerMapApplying}
        preview={customerMapPreview}
        error={customerMapError}
        testIdPrefix={tid('customer-bank-map')}
        onClose={closeCustomerMap}
        onChoose={mode => void applyCustomerMap(mode)}
      />
    </div>
  );
};

export default StepClassifyImp;
