import React, { useEffect, useMemo, useState } from 'react';
import { SearchInput } from '@linm-soft-org/linm-web-common-components';
import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import {
  AccountSearchInput,
  createAccountSearchConfig,
  erpFinanceAccountSearchApi,
  useAccountSearchAsOfDate,
} from '../../../../../components/search';
import { CustomerSearchField } from '../../../../../components/search/CustomerSearchField';
import type { BankStatementImportStatementLine } from '../../../../../services/kt/bankStatementImportModels';
import type {
  BankStatementImportBatchLine,
  BankStatementImportLink,
} from '../../../../../services/kt/bankStatementImportModels';
import type { PostingReasonInitItem } from '../../../../../services/voucherInit/endpoint';
import type { CostCodeLookupItem, CompanyCodeLookupItem } from './createClassifyLookupConfigs';
import { resolvePostingReasonAccounts } from '../../../../../features/kt/cash-voucher/shared/utils/applyPostingReasonAccounts';
import { parseExpenseItemCodes } from '../../../../../utils/postingReasonVoucherAccess';
import {
  collectBatchLinesForRefs,
  expandLinksWithAmountCompanions,
  normalizeBulkRef,
  resolveLinkedBatchRefsForStatement,
} from '../../../../../utils/extractBatchRefs';
import { isBatchHubCandidate } from '../../../../../utils/batchStatementLinkEligibility';
import df from '../../../../../styles/documentForm.module.css';
import styles from './StepClassifyImp.module.css';

export type ClassifyLineKind = 'receipt' | 'payment';

const COL_COUNT = 14;
const COL_COUNT_WITH_FEE_TAX = 16;
/** IMP lines store mã ĐT — SearchInput value = code (not Guid). */
const IMP_CUSTOMER_SEARCH_OPTS = { valueIsCode: true as const };

function lineAmount(l: BankStatementImportStatementLine): number {
  return l.creditAmount || l.debitAmount || l.amount || 0;
}

function lineKind(l: BankStatementImportStatementLine): ClassifyLineKind {
  if ((l.creditAmount ?? 0) > 0) return 'receipt';
  if ((l.debitAmount ?? 0) > 0) return 'payment';
  if (l.suggestedVoucherType === 'bao_co') return 'receipt';
  if (l.suggestedVoucherType === 'bao_no') return 'payment';
  return 'payment';
}

function formatImportDate(raw?: string): string {
  const s = (raw || '').trim();
  if (!s) return '—';
  return s;
}

function batchDetailErrorCount(details: BankStatementImportBatchLine[]): number {
  return details.filter(b => {
    if ((b.lineStatus || 'Draft') === 'Skipped') return false;
    if (b.errorCode) return true;
    if (!b.companyCode?.trim()) return true;
    if (!b.postingReasonCode?.trim()) return true;
    if (!b.contraAccountCode?.trim()) return true;
    if (!b.customerCode?.trim()) return true;
    return false;
  }).length;
}

type FlatUnit = {
  kind: 'flat';
  line: BankStatementImportStatementLine;
  pageIndex: number;
};

type GroupMember = { line: BankStatementImportStatementLine; pageIndex: number };

type GroupUnit = {
  kind: 'group';
  batchRef: string;
  refs: string[];
  /** Sao kê chính (hub / Chi ưu tiên). */
  master: GroupMember;
  /** Sao kê phụ cùng lô — chỉ khi ≥2 GD; không có thì bỏ qua. */
  subs: GroupMember[];
  /** Dòng thanh toán lô — fill ĐT/ĐK. */
  details: BankStatementImportBatchLine[];
};

type RenderUnit = FlatUnit | GroupUnit;

/** Chọn sao kê chính trong group — parity Map GD/Lô (Chi hub ưu tiên). */
function pickGroupMaster(members: GroupMember[]): { master: GroupMember; subs: GroupMember[] } {
  if (members.length === 1) return { master: members[0], subs: [] };
  const scored = members.map(m => {
    const l = m.line;
    let score = 0;
    if ((l.debitAmount ?? 0) > 0) score += 100;
    if (isBatchHubCandidate(l)) score += 40;
    if ((l.creditAmount ?? 0) > 0) score -= 20;
    score += Math.min(20, Math.round(lineAmount(l) / 1_000_000));
    return { m, score, pageIndex: m.pageIndex };
  });
  scored.sort((a, b) => b.score - a.score || a.pageIndex - b.pageIndex);
  const master = scored[0].m;
  const subs = members.filter(m => m.line.id !== master.line.id);
  return { master, subs };
}

export interface ClassifyLinesGridProps {
  lines: BankStatementImportStatementLine[];
  /** Dòng lô — detail fill khi GD đã link. */
  batchLines?: BankStatementImportBatchLine[];
  /** Links sao kê ↔ lô (rowIndex → batchRef). */
  links?: Array<Pick<
    BankStatementImportLink,
    'statementRowIndex' | 'batchRef' | 'statementImportReference' | 'statementReferenceCode'
  >>;
  /** 0-based offset for STT across client pages */
  rowOffset?: number;
  /**
   * Hiện cột Phí/Thuế theo toàn bộ IMP (không theo trang/tab hiện tại).
   * Nếu không truyền — suy từ `lines` trên lưới.
   */
  showFeeTaxColumns?: boolean;
  postingReasonSearchConfig: SearchInputConfig<PostingReasonInitItem>;
  postingReasonByCode: Map<string, PostingReasonInitItem>;
  /** Index ĐK theo mã CP — chọn CP → auto map ĐK + TK đối ứng. */
  postingReasonByExpenseCode?: Map<string, PostingReasonInitItem>;
  costCodeSearchConfig: SearchInputConfig<CostCodeLookupItem>;
  companyCodeSearchConfig: SearchInputConfig<CompanyCodeLookupItem>;
  /** Kept for parent parity / future tooltip; grid shows code only. */
  companyByCode?: Map<string, CompanyCodeLookupItem>;
  selectedIds?: Set<string>;
  focusedLineId?: string | null;
  onToggleSelect?: (id: string) => void;
  onToggleSelectAllPage?: (checked: boolean) => void;
  onFocusLine?: (id: string) => void;
  onPatch: (id: string, patch: Partial<BankStatementImportStatementLine>) => void;
  onPatchBatch?: (id: string, patch: Partial<BankStatementImportBatchLine>) => void;
  /** Chọn ĐT — parent mở confirm map STK khi dòng có bankAccountCode. */
  onCustomerSelect?: (
    line: BankStatementImportStatementLine,
    customer: { code: string; name: string },
  ) => void;
  testIdPrefix: string;
}

export const ClassifyLinesGrid: React.FC<ClassifyLinesGridProps> = ({
  lines,
  batchLines = [],
  links = [],
  rowOffset = 0,
  showFeeTaxColumns,
  postingReasonSearchConfig,
  postingReasonByCode,
  postingReasonByExpenseCode,
  costCodeSearchConfig,
  companyCodeSearchConfig,
  selectedIds,
  focusedLineId,
  onToggleSelect,
  onToggleSelectAllPage,
  onFocusLine,
  onPatch,
  onPatchBatch,
  onCustomerSelect,
  testIdPrefix,
}) => {
  const accountSearchOptions = useAccountSearchAsOfDate(undefined);
  const accountSearchConfig = useMemo(
    () => createAccountSearchConfig(accountSearchOptions),
    [accountSearchOptions],
  );

  const effectiveLinks = useMemo(
    () => expandLinksWithAmountCompanions(lines, links, batchLines),
    [lines, links, batchLines],
  );

  const refsByLineId = useMemo(() => {
    const map = new Map<string, string[]>();
    for (const line of lines) {
      const resolved = resolveLinkedBatchRefsForStatement(line, effectiveLinks, batchLines);
      if (resolved.length > 0) map.set(line.id, resolved);
    }
    return map;
  }, [lines, effectiveLinks, batchLines]);

  const renderUnits = useMemo((): RenderUnit[] => {
    const units: RenderUnit[] = [];
    const consumed = new Set<string>();
    for (let i = 0; i < lines.length; i += 1) {
      const line = lines[i];
      if (consumed.has(line.id)) continue;
      const refs = refsByLineId.get(line.id) ?? [];
      if (refs.length === 0) {
        units.push({ kind: 'flat', line, pageIndex: i });
        continue;
      }
      const members: GroupMember[] = [{ line, pageIndex: i }];
      consumed.add(line.id);
      const allRefs = new Set(refs);
      for (let j = i + 1; j < lines.length; j += 1) {
        const other = lines[j];
        if (consumed.has(other.id)) continue;
        const otherRefs = refsByLineId.get(other.id) ?? [];
        if (!otherRefs.some(r => refs.some(x => normalizeBulkRef(x) === normalizeBulkRef(r)))) {
          continue;
        }
        members.push({ line: other, pageIndex: j });
        consumed.add(other.id);
        for (const r of otherRefs) allRefs.add(r);
      }
      const refList = [...allRefs];
      const { master, subs } = pickGroupMaster(members);
      units.push({
        kind: 'group',
        batchRef: refList[0],
        refs: refList,
        master,
        subs,
        details: collectBatchLinesForRefs(refList, batchLines),
      });
    }
    return units;
  }, [lines, refsByLineId, batchLines]);

  const [expandedRefs, setExpandedRefs] = useState<Set<string>>(() => new Set());

  useEffect(() => {
    const next = new Set<string>();
    for (const u of renderUnits) {
      if (u.kind === 'group') next.add(u.batchRef);
    }
    setExpandedRefs(prev => {
      // Default expanded; keep user-collapsed only if still present
      const merged = new Set(next);
      for (const ref of prev) {
        if (!next.has(ref) && prev.has(ref)) {
          // dropped
        }
      }
      // Re-open all groups on page change / new links (SSOT: expand default)
      return merged;
    });
  }, [renderUnits]);

  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const showFeeTax = showFeeTaxColumns
    ?? lines.some(l => (l.feeAmount ?? 0) > 0 || (l.taxAmount ?? 0) > 0);
  const colCount = showFeeTax ? COL_COUNT_WITH_FEE_TAX : COL_COUNT;
  const allPageSelected = lines.length > 0 && lines.every(l => selectedIds?.has(l.id));
  const somePageSelected = lines.some(l => selectedIds?.has(l.id));

  const toggleExpand = (batchRef: string) => {
    setExpandedRefs(prev => {
      const next = new Set(prev);
      if (next.has(batchRef)) next.delete(batchRef);
      else next.add(batchRef);
      return next;
    });
  };

  const renderClassifyCells = (
    opts: {
      keyPrefix: string;
      kind: ClassifyLineKind;
      customerCode?: string;
      customerName?: string;
      prefillName?: string;
      prefillBank?: string;
      prefillBankName?: string;
      postingReasonCode?: string;
      contraAccountCode?: string;
      costCode?: string;
      companyCode?: string;
      onSelectCustomer: (c: { code: string; name: string }) => void;
      onClearCustomer: () => void;
      onPatchFields: (patch: {
        postingReasonCode?: string;
        contraAccountCode?: string;
        costCode?: string;
        companyCode?: string;
      }) => void;
    },
  ) => {
    const reason = opts.postingReasonCode
      ? postingReasonByCode.get(opts.postingReasonCode)
      : undefined;
    return (
      <>
        <td data-testid={tid(`${opts.keyPrefix}-customer`)} onClick={e => e.stopPropagation()}>
          <CustomerSearchField
            testIdPrefix={tid(`${opts.keyPrefix}-customer`)}
            className={styles.lookupCell}
            customerId={opts.customerCode || ''}
            customerCode={opts.customerCode || ''}
            customerName={opts.customerName || ''}
            singleField
            defaultCustomerType="Both"
            searchConfigOptions={IMP_CUSTOMER_SEARCH_OPTS}
            createPrefill={{
              name: opts.prefillName,
              bankAccountNumber: opts.prefillBank,
              bankName: opts.prefillBankName,
            }}
            onSelect={c => opts.onSelectCustomer({ code: c.code, name: c.name })}
            onClear={opts.onClearCustomer}
            placeholder="Đối tượng..."
          />
        </td>
        <td
          data-testid={tid(`${opts.keyPrefix}-posting`)}
          onClick={e => e.stopPropagation()}
          title={reason?.name || undefined}
        >
          <SearchInput
            config={postingReasonSearchConfig}
            value={opts.postingReasonCode || ''}
            primaryDisplay={opts.postingReasonCode || ''}
            onChange={(r: PostingReasonInitItem) => {
              const accounts = resolvePostingReasonAccounts(opts.kind, r);
              const linkedCost = parseExpenseItemCodes(r.expenseItemCode)[0];
              opts.onPatchFields({
                postingReasonCode: r.code,
                contraAccountCode: accounts.counterAccountCode || opts.contraAccountCode,
                ...(linkedCost ? { costCode: linkedCost } : {}),
              });
            }}
            onClear={() => opts.onPatchFields({ postingReasonCode: '' })}
            showLabel={false}
            showSecondaryInput={false}
            placeholder="Định khoản..."
            className={styles.lookupCell}
          />
        </td>
        <td data-testid={tid(`${opts.keyPrefix}-contra`)} onClick={e => e.stopPropagation()}>
          <AccountSearchInput
            config={accountSearchConfig}
            api={erpFinanceAccountSearchApi}
            className={styles.lookupCell}
            value={opts.contraAccountCode || ''}
            primaryDisplay={opts.contraAccountCode || ''}
            onChange={a => opts.onPatchFields({ contraAccountCode: a.code })}
            onClear={() => opts.onPatchFields({ contraAccountCode: '' })}
            showLabel={false}
            showSecondaryInput={false}
            placeholder="TK đối ứng..."
          />
        </td>
        <td data-testid={tid(`${opts.keyPrefix}-cost`)} onClick={e => e.stopPropagation()}>
          <SearchInput
            config={costCodeSearchConfig}
            value={opts.costCode || ''}
            primaryDisplay={opts.costCode || ''}
            onChange={(c: CostCodeLookupItem) => {
              const linked = postingReasonByExpenseCode?.get(c.code.toUpperCase())
                ?? postingReasonByExpenseCode?.get(c.code);
              const contraFromExpense = (c.accountCode || '').trim();
              const accounts = linked
                ? resolvePostingReasonAccounts(opts.kind, linked)
                : null;
              const contra = contraFromExpense
                || accounts?.counterAccountCode
                || opts.contraAccountCode
                || '';
              opts.onPatchFields({
                costCode: c.code,
                ...(linked ? { postingReasonCode: linked.code } : {}),
                ...(contra ? { contraAccountCode: contra } : {}),
              });
            }}
            onClear={() => opts.onPatchFields({ costCode: '' })}
            showLabel={false}
            showSecondaryInput={false}
            placeholder="Mã CP..."
            className={styles.lookupCell}
          />
        </td>
        <td data-testid={tid(`${opts.keyPrefix}-company`)} onClick={e => e.stopPropagation()}>
          <SearchInput
            config={companyCodeSearchConfig}
            value={opts.companyCode || ''}
            primaryDisplay={opts.companyCode || ''}
            onChange={(c: CompanyCodeLookupItem) => opts.onPatchFields({ companyCode: c.code })}
            onClear={() => opts.onPatchFields({ companyCode: '' })}
            showLabel={false}
            showSecondaryInput={false}
            placeholder="Đơn vị..."
            className={styles.lookupCell}
          />
        </td>
      </>
    );
  };

  const renderMasterRoClassify = (
    keyPrefix: string,
    errCount: number,
    hint = 'Điền trên dòng lô',
  ) => (
    <td colSpan={5} className={styles.masterClassifyHint} data-testid={tid(`${keyPrefix}-classify-ro`)}>
      <span>{hint}</span>
      {errCount > 0 ? (
        <span className={styles.errorBadge} title={`${errCount} dòng lô thiếu thông tin`}>
          {errCount} lỗi lô
        </span>
      ) : null}
    </td>
  );

  const renderMasterRow = (
    l: BankStatementImportStatementLine,
    absIndex: number,
    opts: {
      expand?: { batchRef: string; open: boolean; onToggle: () => void };
      batchLabel?: string;
      errCount?: number;
      showErrorBadge?: boolean;
      subCount?: number;
      batchDetailCount?: number;
    },
  ) => {
    const amountClass = lineKind(l) === 'receipt' ? styles.amountCredit : styles.amountDebit;
    const isFocused = focusedLineId === l.id;
    const isChecked = selectedIds?.has(l.id) ?? false;
    const errCount = opts.errCount ?? 0;
    const hasChildren = (opts.subCount ?? 0) > 0 || (opts.batchDetailCount ?? 0) > 0;
    return (
      <tr
        key={l.id}
        className={[
          df.lineRow,
          styles.masterRow,
          styles.groupMaster,
          isFocused ? styles.rowFocused : '',
          isChecked ? styles.rowSelected : '',
          errCount > 0 ? styles.rowHasError : '',
        ].filter(Boolean).join(' ')}
        data-testid={tid(`line-${absIndex}`)}
        onClick={() => {
          onFocusLine?.(l.id);
          if (opts.expand && !opts.expand.open && hasChildren) opts.expand.onToggle();
        }}
      >
        <td onClick={e => e.stopPropagation()}>
          <input
            type="checkbox"
            checked={isChecked}
            onChange={() => onToggleSelect?.(l.id)}
            aria-label={`Chọn dòng ${absIndex + 1}`}
            data-testid={tid(`line-${absIndex}-check`)}
          />
        </td>
        <td>
          <div className={styles.sttCell}>
            <span className={styles.sttNo}>{absIndex + 1}</span>
            {opts.expand && hasChildren ? (
              <button
                type="button"
                className={styles.expandBtn}
                aria-expanded={opts.expand.open}
                aria-label={opts.expand.open ? 'Thu gọn group lô' : 'Mở rộng group lô'}
                data-testid={tid(`line-${absIndex}-expand`)}
                onClick={e => {
                  e.stopPropagation();
                  opts.expand?.onToggle();
                }}
              >
                <svg
                  className={`${styles.expandIcon} ${opts.expand.open ? styles.expandIconOpen : ''}`}
                  viewBox="0 0 16 16"
                  aria-hidden
                >
                  <path
                    d="M6 3.5 11 8l-5 4.5"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
            ) : null}
          </div>
        </td>
        <td className={styles.dateCell}>{formatImportDate(l.transactionDate)}</td>
        <td>
          <div className={styles.roleBadges}>
            <span className={styles.badgeMaster}>Sao kê chính</span>
            {(opts.subCount ?? 0) > 0 ? (
              <span className={styles.badgeMeta}>{opts.subCount} GD phụ</span>
            ) : null}
          </div>
          <div className={styles.counterparty}>
            {l.counterpartyName || '—'}
          </div>
          {l.bankAccountCode ? (
            <div className={styles.metaLine}>{l.bankAccountCode}</div>
          ) : null}
          {l.partnerBankName ? (
            <div className={styles.metaLine}>{l.partnerBankName}</div>
          ) : null}
          {opts.batchLabel ? (
            <div className={styles.batchRefTag} title={opts.batchLabel}>
              Lô {opts.batchLabel}
            </div>
          ) : null}
        </td>
        <td className={`${df.tdAmount} ${amountClass}`}>
          {lineAmount(l).toLocaleString('vi-VN')}
        </td>
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.feeAmount ?? 0) > 0 ? (l.feeAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.taxAmount ?? 0) > 0 ? (l.taxAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        <td>
          <div className={styles.descFull}>
            {l.description?.trim() || '—'}
          </div>
        </td>
        <td>
          <div className={styles.refCell}>{l.referenceCode || '—'}</div>
        </td>
        <td>
          <div className={styles.pathCell} title={l.importReference || undefined}>
            {l.importReference || '—'}
          </div>
        </td>
        <td>
          <div className={styles.noteCell}>
            {l.expenseNote?.trim() || '—'}
          </div>
        </td>
        {renderMasterRoClassify(
          `line-${absIndex}`,
          opts.showErrorBadge ? errCount : 0,
        )}
      </tr>
    );
  };

  /** Sao kê phụ cùng lô — chỉ hiển thị khi có ≥2 GD; RO, không fill classify. */
  const renderSubStatementRow = (
    l: BankStatementImportStatementLine,
    absIndex: number,
    subIndex: number,
    groupRef: string,
  ) => {
    const amountClass = lineKind(l) === 'receipt' ? styles.amountCredit : styles.amountDebit;
    const isFocused = focusedLineId === l.id;
    const isChecked = selectedIds?.has(l.id) ?? false;
    return (
      <tr
        key={`sub-${l.id}`}
        className={[
          df.lineRow,
          styles.subStatementRow,
          isFocused ? styles.rowFocused : '',
          isChecked ? styles.rowSelected : '',
        ].filter(Boolean).join(' ')}
        data-testid={tid(`sub-${groupRef}-${subIndex}`)}
        onClick={() => onFocusLine?.(l.id)}
      >
        <td onClick={e => e.stopPropagation()}>
          <input
            type="checkbox"
            checked={isChecked}
            onChange={() => onToggleSelect?.(l.id)}
            aria-label={`Chọn sao kê phụ ${absIndex + 1}`}
            data-testid={tid(`sub-${absIndex}-check`)}
          />
        </td>
        <td>
          <div className={styles.sttCell}>
            <span className={styles.sttNo}>{absIndex + 1}</span>
            <span className={styles.groupMemberMark} title="Sao kê phụ cùng lô">↳</span>
          </div>
        </td>
        <td className={styles.dateCell}>{formatImportDate(l.transactionDate)}</td>
        <td>
          <div className={styles.roleBadges}>
            <span className={styles.badgeSub}>Sao kê phụ</span>
          </div>
          <div className={styles.counterparty}>
            {l.counterpartyName || '—'}
          </div>
          {l.bankAccountCode ? (
            <div className={styles.metaLine}>{l.bankAccountCode}</div>
          ) : null}
          {l.partnerBankName ? (
            <div className={styles.metaLine}>{l.partnerBankName}</div>
          ) : null}
        </td>
        <td className={`${df.tdAmount} ${amountClass}`}>
          {lineAmount(l).toLocaleString('vi-VN')}
        </td>
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.feeAmount ?? 0) > 0 ? (l.feeAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.taxAmount ?? 0) > 0 ? (l.taxAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        <td>
          <div className={styles.descFull}>{l.description?.trim() || '—'}</div>
        </td>
        <td>
          <div className={styles.refCell}>{l.referenceCode || '—'}</div>
        </td>
        <td>
          <div className={styles.pathCell} title={l.importReference || undefined}>
            {l.importReference || '—'}
          </div>
        </td>
        <td>
          <div className={styles.noteCell}>{l.expenseNote?.trim() || '—'}</div>
        </td>
        {renderMasterRoClassify(`sub-${absIndex}`, 0, 'Cùng lô — điền trên dòng lô')}
      </tr>
    );
  };

  const renderFlatRow = (l: BankStatementImportStatementLine, pageIndex: number) => {
    const absIndex = rowOffset + pageIndex;
    const kind = lineKind(l);
    const isFocused = focusedLineId === l.id;
    const isChecked = selectedIds?.has(l.id) ?? false;
    const amountClass = kind === 'receipt' ? styles.amountCredit : styles.amountDebit;
    return (
      <tr
        key={l.id}
        className={`${df.lineRow} ${isFocused ? styles.rowFocused : ''} ${isChecked ? styles.rowSelected : ''}`}
        data-testid={tid(`line-${absIndex}`)}
        onClick={() => onFocusLine?.(l.id)}
      >
        <td onClick={e => e.stopPropagation()}>
          <input
            type="checkbox"
            checked={isChecked}
            onChange={() => onToggleSelect?.(l.id)}
            aria-label={`Chọn dòng ${absIndex + 1}`}
            data-testid={tid(`line-${absIndex}-check`)}
          />
        </td>
        <td>{absIndex + 1}</td>
        <td className={styles.dateCell}>{formatImportDate(l.transactionDate)}</td>
        <td>
          <div className={styles.counterparty}>
            {l.counterpartyName || '—'}
          </div>
          {l.bankAccountCode ? (
            <div className={styles.metaLine}>{l.bankAccountCode}</div>
          ) : null}
          {l.partnerBankName ? (
            <div className={styles.metaLine}>{l.partnerBankName}</div>
          ) : null}
        </td>
        <td className={`${df.tdAmount} ${amountClass}`}>
          {lineAmount(l).toLocaleString('vi-VN')}
        </td>
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.feeAmount ?? 0) > 0 ? (l.feeAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        {showFeeTax && (
          <td className={df.tdAmount}>
            {(l.taxAmount ?? 0) > 0 ? (l.taxAmount ?? 0).toLocaleString('vi-VN') : '—'}
          </td>
        )}
        <td>
          <div className={styles.descFull}>
            {l.description?.trim() || '—'}
          </div>
        </td>
        <td>
          <div className={styles.refCell}>{l.referenceCode || '—'}</div>
        </td>
        <td>
          <div className={styles.pathCell} title={l.importReference || undefined}>
            {l.importReference || '—'}
          </div>
        </td>
        <td>
          <div className={styles.noteCell}>
            {l.expenseNote?.trim() || '—'}
          </div>
        </td>
        {renderClassifyCells({
          keyPrefix: `line-${absIndex}`,
          kind,
          customerCode: l.customerCode,
          customerName: l.customerName,
          prefillName: l.counterpartyName || undefined,
          prefillBank: l.bankAccountCode || undefined,
          prefillBankName: l.partnerBankName || undefined,
          postingReasonCode: l.postingReasonCode,
          contraAccountCode: l.contraAccountCode,
          costCode: l.costCode,
          companyCode: l.companyCode,
          onSelectCustomer: c => {
            if (onCustomerSelect) {
              onCustomerSelect(l, c);
              return;
            }
            onPatch(l.id, { customerCode: c.code, customerName: c.name });
          },
          onClearCustomer: () => onPatch(l.id, { customerCode: '', customerName: '' }),
          onPatchFields: patch => onPatch(l.id, patch),
        })}
      </tr>
    );
  };

  const renderDetailRow = (
    b: BankStatementImportBatchLine,
    masterKind: ClassifyLineKind,
    detailIndex: number,
    groupRef: string,
  ) => {
    const keyPrefix = `batch-${b.id}`;
    return (
      <tr
        key={`detail-${b.id}`}
        className={`${df.lineRow} ${styles.detailRow} ${styles.batchDetailRow}`}
        data-testid={tid(`batch-${groupRef}-${detailIndex}`)}
      >
        <td />
        <td className={styles.detailStt}>↳</td>
        <td className={styles.dateCell}>{formatImportDate(b.sheetDate)}</td>
        <td>
          <div className={styles.roleBadges}>
            <span className={styles.badgeBatch}>Dòng lô</span>
          </div>
          <div className={styles.counterparty}>{b.beneficiaryName || '—'}</div>
          {b.accountNumber ? <div className={styles.metaLine}>{b.accountNumber}</div> : null}
          {b.bankName ? <div className={styles.metaLine}>{b.bankName}</div> : null}
          {b.batchRef ? <div className={styles.batchRefTag}>Lô {b.batchRef}</div> : null}
        </td>
        <td className={`${df.tdAmount} ${styles.amountDebit}`}>
          {(b.amount ?? 0).toLocaleString('vi-VN')}
        </td>
        {showFeeTax && <td className={df.tdAmount}>—</td>}
        {showFeeTax && <td className={df.tdAmount}>—</td>}
        <td>
          <div className={styles.descFull}>{b.description?.trim() || '—'}</div>
        </td>
        <td>
          <div className={styles.refCell}>{b.ftNumber || '—'}</div>
        </td>
        <td>
          <div className={styles.pathCell} title={b.sourcePath || undefined}>
            {b.sourcePath || '—'}
          </div>
        </td>
        <td>
          <div className={styles.noteCell}>{b.staffNote?.trim() || '—'}</div>
        </td>
        {renderClassifyCells({
          keyPrefix,
          kind: masterKind,
          customerCode: b.customerCode,
          customerName: b.customerName,
          prefillName: b.beneficiaryName || undefined,
          prefillBank: b.accountNumber || undefined,
          prefillBankName: b.bankName || undefined,
          postingReasonCode: b.postingReasonCode,
          contraAccountCode: b.contraAccountCode,
          costCode: b.costCode,
          companyCode: b.companyCode,
          onSelectCustomer: c => {
            onPatchBatch?.(b.id, { customerCode: c.code, customerName: c.name });
          },
          onClearCustomer: () => onPatchBatch?.(b.id, { customerCode: '', customerName: '' }),
          onPatchFields: patch => onPatchBatch?.(b.id, patch),
        })}
      </tr>
    );
  };

  return (
    <div className={`${df.linesSection} ${styles.linesFill}`} data-testid={tid('lines')}>
      <div className={`${df.tableWrapper} ${styles.tableScroll}`}>
        <table className={`${df.linesTable} ${styles.classifyTable}`}>
          <thead>
            <tr>
              <th style={{ width: 36 }}>
                <input
                  type="checkbox"
                  checked={allPageSelected}
                  ref={el => {
                    if (el) el.indeterminate = !allPageSelected && somePageSelected;
                  }}
                  onChange={e => onToggleSelectAllPage?.(e.target.checked)}
                  aria-label="Chọn tất cả trang"
                  data-testid={tid('select-all')}
                />
              </th>
              <th style={{ width: 48 }}>#</th>
              <th style={{ width: 120 }}>Ngày</th>
              <th style={{ minWidth: 140 }}>Đối tượng</th>
              <th style={{ width: 110 }}>Số tiền</th>
              {showFeeTax && <th style={{ width: 90 }}>Phí</th>}
              {showFeeTax && <th style={{ width: 90 }}>Thuế</th>}
              <th style={{ minWidth: 220 }}>Nội dung chuyển khoản</th>
              <th style={{ minWidth: 120 }}>Mã tham chiếu</th>
              <th style={{ minWidth: 140 }}>Chứng từ gốc</th>
              <th style={{ minWidth: 100 }}>Ghi chú</th>
              <th style={{ minWidth: 160 }} title="Chọn đối tượng danh mục">Đối tượng</th>
              <th style={{ minWidth: 150 }}>Định khoản NV</th>
              <th style={{ minWidth: 120 }}>TK đối ứng</th>
              <th style={{ minWidth: 100 }}>Mã CP</th>
              <th style={{ minWidth: 140 }}>Đơn vị</th>
            </tr>
          </thead>
          <tbody>
            {lines.length === 0 ? (
              <tr>
                <td colSpan={colCount} className={styles.emptyCell}>Không có dòng trên tab này</td>
              </tr>
            ) : (
              renderUnits.flatMap((unit): React.ReactElement[] => {
                if (unit.kind === 'flat') {
                  return [renderFlatRow(unit.line, unit.pageIndex)];
                }
                const hasSubs = unit.subs.length > 0;
                const hasBatchDetails = unit.details.length > 0;
                const hasChildren = hasSubs || hasBatchDetails;
                const open = hasChildren && expandedRefs.has(unit.batchRef);
                const errCount = batchDetailErrorCount(unit.details);
                const masterKind = lineKind(unit.master.line);
                const gdTotal = 1 + unit.subs.length;
                const batchLabel = gdTotal > 1
                  ? `${unit.refs.join(', ')} · ${gdTotal} GD`
                  : unit.refs.join(', ');
                const rows: React.ReactElement[] = [];
                const masterAbs = rowOffset + unit.master.pageIndex;
                rows.push(renderMasterRow(unit.master.line, masterAbs, {
                  expand: hasChildren
                    ? {
                      batchRef: unit.batchRef,
                      open,
                      onToggle: () => toggleExpand(unit.batchRef),
                    }
                    : undefined,
                  batchLabel,
                  errCount,
                  showErrorBadge: true,
                  subCount: unit.subs.length,
                  batchDetailCount: unit.details.length,
                }));
                if (open) {
                  // 1) Sao kê phụ (chỉ khi có) — bỏ qua nếu 1 GD
                  if (hasSubs) {
                    rows.push(
                      <tr key={`sec-sub-${unit.batchRef}`} className={styles.sectionHeaderRow}>
                        <td colSpan={colCount}>
                          Sao kê phụ · {unit.subs.length} GD cùng lô
                        </td>
                      </tr>,
                    );
                    unit.subs.forEach((s, si) => {
                      rows.push(renderSubStatementRow(
                        s.line,
                        rowOffset + s.pageIndex,
                        si,
                        unit.batchRef,
                      ));
                    });
                  }
                  // 2) Dòng lô — fill classify
                  if (hasBatchDetails) {
                    rows.push(
                      <tr key={`sec-batch-${unit.batchRef}`} className={styles.sectionHeaderRow}>
                        <td colSpan={colCount}>
                          Dòng lô · {unit.details.length} — điền ĐT / ĐK / CP / ĐV
                        </td>
                      </tr>,
                    );
                    unit.details.forEach((b, di) => {
                      rows.push(renderDetailRow(b, masterKind, di, unit.batchRef));
                    });
                  }
                }
                return rows;
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
