/**
 * Extract bank batch reference codes from a transaction description.
 * Based on REVA's bank-statement-mb-batch-reconcile.mjs logic.
 *
 * Batch refs are 14–20 digit numbers starting with "25",
 * or INHOUSE patterns like "25011016424 145673-INHOUSE".
 */

import { sumBatchLineAmounts } from './batchPaymentStatus';

/** Score a batch ref candidate — higher = more likely correct. */
function scoreBulkRefCandidate(ref: string): number {
  if (ref.endsWith('-INHOUSE')) return 20;
  // Prefixed by year digit 25/26… (MB/TPB batch refs 2025–2026+)
  if (/^2[5-9]\d{12,16}$/.test(ref)) return 100;
  if (/^2[5-9]/.test(ref)) return 50;
  return 0;
}

/** Join fragmented INHOUSE ref groups. */
function joinInhouseRefGroups(groups: string[]): string {
  if (!groups.length) return '';
  const isYearPrefixed = (s: string) => /^2[5-9]/.test(s);
  const joinedAll = groups.join('');
  if (joinedAll.length >= 11 && joinedAll.length <= 22 && isYearPrefixed(joinedAll)) return joinedAll;
  const last = groups[groups.length - 1];
  if (last.length >= 14 && isYearPrefixed(last)) return last;
  const joined = groups.slice(-2).join('');
  if (joined.length >= 11 && joined.length <= 22 && isYearPrefixed(joined)) return joined;
  const best = [...groups].reverse().find(g => g.length >= 11 && isYearPrefixed(g));
  return best || joinedAll || joined;
}

/**
 * Extract bulk ref candidates from a transaction description string.
 * Returns sorted array (best candidate first).
 */
export function extractBulkRefsFromDescription(desc: string | undefined | null): string[] {
  const s = String(desc ?? '');
  if (!s.trim()) return [];
  const refs = new Set<string>();

  // Pattern 1: INHOUSE suffix — e.g. "26202173 60255976-INHOUSE"
  for (const m of s.matchAll(/-\s*INHOUSE/gi)) {
    const end = m.index;
    let pos = end - 1;
    while (pos >= 0) {
      const ch = s[pos];
      if (ch === '.') break;
      if (!/[\d\s]/.test(ch)) break;
      pos -= 1;
    }
    const groups = s
      .slice(pos + 1, end)
      .trim()
      .split(/\s+/)
      .filter(g => /^\d+$/.test(g));
    const joined = joinInhouseRefGroups(groups);
    if (joined.length >= 11 && joined.length <= 22) {
      refs.add(joined);
      refs.add(`${joined}-INHOUSE`);
    }
  }

  // Pattern 2: 14–20 consecutive digits starting with 25–29 (năm lô)
  const norm = s.replace(/\s/g, '').toUpperCase();
  for (const m of norm.matchAll(/\d{14,20}/g)) {
    const digits = m[0];
    if (/^2[5-9]/.test(digits) && digits.length >= 14) refs.add(digits);
  }

  // Pattern 3: Any 25–29-prefixed sequence 11–22 digits
  const digitsOnly = s.replace(/\D/g, '');
  for (const m of digitsOnly.matchAll(/2[5-9]\d{6,19}/g)) {
    const digits = m[0];
    if (digits.length >= 11 && digits.length <= 22) refs.add(digits);
  }

  return [...refs].sort((a, b) => scoreBulkRefCandidate(b) - scoreBulkRefCandidate(a));
}

/**
 * Check if a row's description has batch references that match
 * any of the batch payment files loaded from parsed batch data.
 */
export function findMatchingBatchRefs(
  detectedRefs: string[],
  parsedBatchRefs: string[],
): string[] {
  if (!detectedRefs.length || !parsedBatchRefs.length) return [];

  const matched: string[] = [];
  for (const ref of detectedRefs) {
    const normalized = ref.replace(/-INHOUSE$/i, '');
    if (parsedBatchRefs.some(br => br === normalized || br === ref)) {
      matched.push(ref);
    }
  }
  return matched;
}

/**
 * Normalize a batch ref for comparison.
 */
export function normalizeBulkRef(ref: string): string {
  return ref.replace(/-INHOUSE$/i, '').replace(/\s/g, '');
}

export type StatementBatchLinkLike = {
  statementRowIndex: number;
  batchRef: string;
  statementImportReference?: string;
  statementReferenceCode?: string;
};

export type StatementLineForBatchLink = {
  id?: string;
  rowIndex: number;
  importReference?: string;
  referenceCode?: string;
  transactionDate?: string;
  debitAmount?: number;
  creditAmount?: number;
  amount?: number;
  counterpartyName?: string;
  partnerBankName?: string;
};

function buildBatchCanonicalMap(batchLines: Array<{ batchRef?: string }>): Map<string, string> {
  const batchNormToCanonical = new Map<string, string>();
  for (const b of batchLines) {
    const raw = (b.batchRef || '').trim();
    if (!raw) continue;
    const norm = normalizeBulkRef(raw);
    if (!norm) continue;
    const prev = batchNormToCanonical.get(norm);
    if (!prev || (!raw.toUpperCase().endsWith('-INHOUSE') && prev.toUpperCase().endsWith('-INHOUSE'))) {
      batchNormToCanonical.set(norm, raw.replace(/-INHOUSE$/i, '') || raw);
    }
  }
  return batchNormToCanonical;
}

function linkMatchesStatement(
  link: StatementBatchLinkLike,
  line: StatementLineForBatchLink,
): boolean {
  const byImp = link.statementImportReference?.trim();
  if (byImp && (line.importReference ?? '').trim() === byImp) return true;
  const byCode = link.statementReferenceCode?.trim();
  if (byCode && (line.referenceCode ?? '').trim() === byCode) return true;
  return link.statementRowIndex === line.rowIndex;
}

function normTxnDateKey(d?: string): string {
  if (!d) return '';
  const s = d.trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) {
    return `${iso[3].padStart(2, '0')}/${iso[2].padStart(2, '0')}/${iso[1]}`;
  }
  const m = s.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return s;
  const dd = m[1].padStart(2, '0');
  const mm = m[2].padStart(2, '0');
  let yyyy = m[3];
  if (yyyy.length === 2) yyyy = `20${yyyy}`;
  return `${dd}/${mm}/${yyyy}`;
}

function statementSignedAmount(line: StatementLineForBatchLink): number {
  const debit = line.debitAmount ?? 0;
  const credit = line.creditAmount ?? 0;
  if (debit > 0) return debit;
  if (credit > 0) return -credit;
  return line.amount || 0;
}

/**
 * Resolve links sao kê → mã lô thật (có dòng `batchLines`).
 * Match theo importReference / referenceCode / rowIndex (parity Map GD/Lô).
 */
export function resolveLinkedBatchRefsForStatement(
  line: StatementLineForBatchLink,
  links: StatementBatchLinkLike[],
  batchLines: Array<{ batchRef?: string }>,
): string[] {
  const batchNormToCanonical = buildBatchCanonicalMap(batchLines);
  const out: string[] = [];
  const seen = new Set<string>();
  for (const link of links) {
    if (!linkMatchesStatement(link, line)) continue;
    const raw = (link.batchRef || '').trim();
    if (!raw) continue;
    const norm = normalizeBulkRef(raw);
    if (!norm || seen.has(norm)) continue;
    const canonical = batchNormToCanonical.get(norm);
    if (!canonical) continue;
    seen.add(norm);
    out.push(canonical);
  }
  return out;
}

/** @deprecated Prefer resolveLinkedBatchRefsForStatement — giữ tương thích gọi theo rowIndex. */
export function resolveLinkedBatchRefsForRow(
  statementRowIndex: number,
  links: StatementBatchLinkLike[],
  batchLines: Array<{ batchRef?: string }>,
): string[] {
  return resolveLinkedBatchRefsForStatement({ rowIndex: statementRowIndex }, links, batchLines);
}

/**
 * Mở rộng links: thêm GD phụ khớp tiền cùng ngày với lô (rule Map GD/Lô ✓ Khớp).
 * VD: hub INHOUSE đã link + GD pool cùng ngày đủ tiền → cùng group.
 */
export function expandLinksWithAmountCompanions<T extends StatementLineForBatchLink & { id: string }>(
  lines: T[],
  links: StatementBatchLinkLike[],
  batchLines: Array<{ batchRef?: string; amount: number; status?: string }>,
): StatementBatchLinkLike[] {
  if (lines.length === 0 || links.length === 0) return links;

  const canonical = buildBatchCanonicalMap(batchLines);
  const out: StatementBatchLinkLike[] = [...links];
  const seen = new Set(
    links.map(l => `${l.statementImportReference ?? l.statementRowIndex}|${normalizeBulkRef(l.batchRef)}`),
  );

  const membersByNorm = new Map<string, T[]>();
  for (const line of lines) {
    const refs = resolveLinkedBatchRefsForStatement(line, links, batchLines);
    for (const ref of refs) {
      const norm = normalizeBulkRef(ref);
      const list = membersByNorm.get(norm) ?? [];
      list.push(line);
      membersByNorm.set(norm, list);
    }
  }

  const linkedIds = new Set<string>();
  for (const list of membersByNorm.values()) {
    for (const l of list) linkedIds.add(l.id);
  }

  for (const [norm, members] of membersByNorm) {
    const canonicalRef = canonical.get(norm);
    if (!canonicalRef) continue;
    const details = batchLines.filter(b => normalizeBulkRef(b.batchRef || '') === norm);
    const { successAmount } = sumBatchLineAmounts(details);
    if (successAmount <= 0) continue;

    let sum = members.reduce((s, l) => s + statementSignedAmount(l), 0);
    if (Math.abs(sum - successAmount) <= 1) continue;

    const dateKeys = new Set(members.map(m => normTxnDateKey(m.transactionDate)).filter(Boolean));
    const fileKeys = new Set(
      members.map(m => {
        const r = (m.importReference || '').trim();
        const i = r.lastIndexOf(':');
        return i > 0 ? r.slice(0, i) : r;
      }).filter(Boolean),
    );

    // Lặp tìm GD phụ đủ phần tiền còn thiếu
    for (let guard = 0; guard < 8 && Math.abs(sum - successAmount) > 1; guard += 1) {
      const need = successAmount - sum;
      let best: T | null = null;
      let bestScore = -1;
      for (const cand of lines) {
        if (linkedIds.has(cand.id)) continue;
        if (resolveLinkedBatchRefsForStatement(cand, links, batchLines).length > 0) continue;
        const dk = normTxnDateKey(cand.transactionDate);
        if (dateKeys.size > 0 && dk && !dateKeys.has(dk)) continue;
        const file = (() => {
          const r = (cand.importReference || '').trim();
          const i = r.lastIndexOf(':');
          return i > 0 ? r.slice(0, i) : r;
        })();
        if (fileKeys.size > 0 && file && !fileKeys.has(file)) continue;
        const amt = statementSignedAmount(cand);
        if (Math.abs(amt - need) > 1) continue;
        let score = 10;
        if (!(cand.counterpartyName || '').trim() && !(cand.partnerBankName || '').trim()) score += 40;
        if ((cand.debitAmount ?? 0) > 0) score += 20;
        if (score > bestScore) {
          bestScore = score;
          best = cand;
        }
      }
      if (!best) break;
      linkedIds.add(best.id);
      members.push(best);
      sum += statementSignedAmount(best);
      const key = `${best.importReference ?? best.rowIndex}|${norm}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({
        statementRowIndex: best.rowIndex,
        statementImportReference: best.importReference,
        statementReferenceCode: best.referenceCode,
        batchRef: canonicalRef,
      });
    }
  }

  return out;
}

/** Collect batch line ids for the given canonical/normalized refs. */
export function collectBatchLinesForRefs<T extends { id: string; batchRef?: string; lineIndex: number }>(
  refs: string[],
  batchLines: T[],
): T[] {
  if (refs.length === 0) return [];
  const norms = new Set(refs.map(normalizeBulkRef).filter(Boolean));
  const byId = new Map<string, T>();
  for (const b of batchLines) {
    const norm = normalizeBulkRef((b.batchRef || '').trim());
    if (!norm || !norms.has(norm)) continue;
    byId.set(b.id, b);
  }
  return [...byId.values()].sort((a, b) => a.lineIndex - b.lineIndex);
}

/**
 * Gom GD cùng lô (share batchRef sau normalize) thành cụm liền nhau.
 * VD: 2 GD map 1 lô → đứng cạnh nhau để Review map group Master/Detail đúng.
 */
export function clusterStatementLinesByBatchLink<T extends StatementLineForBatchLink & { id: string }>(
  lines: T[],
  links: StatementBatchLinkLike[],
  batchLines: Array<{ batchRef?: string; amount?: number; status?: string }>,
): T[] {
  if (lines.length <= 1) return lines;

  const effectiveLinks = expandLinksWithAmountCompanions(
    lines,
    links,
    batchLines.map(b => ({ batchRef: b.batchRef, amount: b.amount ?? 0, status: b.status })),
  );

  const refsById = new Map<string, string[]>();
  for (const line of lines) {
    const resolved = resolveLinkedBatchRefsForStatement(line, effectiveLinks, batchLines);
    if (resolved.length > 0) refsById.set(line.id, resolved);
  }

  const order = new Map(lines.map((l, i) => [l.id, i]));
  const consumed = new Set<string>();
  const out: T[] = [];

  for (const line of lines) {
    if (consumed.has(line.id)) continue;
    const seedRefs = refsById.get(line.id) ?? [];
    if (seedRefs.length === 0) {
      out.push(line);
      consumed.add(line.id);
      continue;
    }

    const norms = new Set(seedRefs.map(normalizeBulkRef).filter(Boolean));
    const group: T[] = [];
    let grew = true;
    while (grew) {
      grew = false;
      for (const other of lines) {
        if (consumed.has(other.id) || group.some(g => g.id === other.id)) continue;
        const otherRefs = refsById.get(other.id) ?? [];
        if (!otherRefs.some(r => norms.has(normalizeBulkRef(r)))) continue;
        group.push(other);
        for (const r of otherRefs) {
          const n = normalizeBulkRef(r);
          if (n) norms.add(n);
        }
        grew = true;
      }
    }

    group.sort((a, b) => (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0));
    for (const g of group) {
      out.push(g);
      consumed.add(g.id);
    }
  }

  return out;
}

