import React from 'react';
import { Button, Modal } from '@linm-soft-org/linm-web-common-components';
import type { BankStatementCustomerBankMapPreview } from '../../../../../services/kt/bankStatementImportModels';
import type { ApplyCustomerBankMapMode } from '../../../../../services/kt/bankStatementImportModels';
import styles from './StepClassifyImp.module.css';

export type CustomerBankMapConfirmProps = {
  open: boolean;
  loading?: boolean;
  applying?: boolean;
  preview: BankStatementCustomerBankMapPreview | null;
  error?: string | null;
  testIdPrefix: string;
  onClose: () => void;
  onChoose: (mode: ApplyCustomerBankMapMode) => void;
};

/**
 * Confirm khi chọn ĐT có STK trên dòng — map danh mục / chứng từ / chỉ dòng hiện tại.
 */
export const CustomerBankMapConfirmModal: React.FC<CustomerBankMapConfirmProps> = ({
  open,
  loading,
  applying,
  preview,
  error,
  testIdPrefix,
  onClose,
  onChoose,
}) => {
  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const busy = Boolean(loading || applying);

  return (
    <Modal
      isOpen={open}
      onClose={() => { if (!busy) onClose(); }}
      title="Thêm số tài khoản vào đối tượng?"
    >
      <p data-testid={tid('question')}>
        Bạn có muốn thêm số tài khoản này vào đối tượng không?
      </p>
      <p className={styles.hint} data-testid={tid('hint')}>
        Lưu ý: Map này hỗ trợ các lần import sau sẽ tự động map giao dịch cho đối tượng này.
      </p>

      {loading && !preview ? (
        <p data-testid={tid('loading')}>Đang tải thông tin…</p>
      ) : null}

      {error ? (
        <p className={styles.error} data-testid={tid('error')}>{error}</p>
      ) : null}

      {preview ? (
        <div className={styles.customerMapPreview} data-testid={tid('preview')}>
          <div><span className={styles.metaLine}>Đối tượng</span></div>
          <div>
            <strong>{preview.customerCode}</strong>
            {' — '}
            {preview.customerName}
            {preview.customerType ? ` (${preview.customerType})` : ''}
          </div>
          <div style={{ marginTop: 8 }}>
            <span className={styles.metaLine}>Số tài khoản</span>
            {' '}
            <strong style={{ fontFamily: 'monospace' }}>
              {preview.bankAccountNumber || '—'}
            </strong>
            {preview.bankAlreadyOnCustomer ? (
              <span className={styles.hint}> · Đã có trên danh mục</span>
            ) : null}
          </div>
          <div style={{ marginTop: 8 }}>
            <div>
              Giao dịch cùng số tài khoản trên phiếu:{' '}
              <strong data-testid={tid('same-bank-count')}>{preview.sameBankLineCount}</strong>
            </div>
            <div style={{ marginTop: 4 }}>
              Giao dịch đã gán đối tượng này:{' '}
              <strong data-testid={tid('existing-customer-count')}>
                {preview.existingCustomerLineCount}
              </strong>
            </div>
          </div>
        </div>
      ) : null}

      <div
        style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 16 }}
        data-testid={tid('actions')}
      >
        <Button
          variant="primary"
          disabled={busy || !preview}
          loading={applying}
          onClick={() => onChoose('catalogAndVoucher')}
          data-testid={tid('opt-catalog-voucher')}
        >
          Thêm vào danh mục và chứng từ
        </Button>
        <Button
          variant="secondary"
          disabled={busy || !preview}
          onClick={() => onChoose('voucherOnly')}
          data-testid={tid('opt-voucher-only')}
        >
          Chỉ map vào chứng từ
        </Button>
        <Button
          variant="secondary"
          disabled={busy}
          onClick={() => onChoose('lineOnly')}
          data-testid={tid('opt-cancel-line')}
        >
          Hủy — chỉ map dòng hiện tại
        </Button>
      </div>
    </Modal>
  );
};
